-- Phase 1 (tenant-key standardization): rewrite function/procedure bodies that
-- reference the legacy org_id COLUMN to use organization_id instead.
--
-- org_id == organization_id today (sync-locked by sync_org_tenant_key()), so each
-- rewrite is exactly behavior-preserving. All statements are CREATE OR REPLACE =
-- atomic body swaps, reversible, and modify NO data. The set was generated by a
-- 145-agent classify->rewrite->adversarial-verify pass (0 rejects) and rehearsed
-- in a ROLLED-BACK prod transaction: 66 applied cleanly, public function count
-- unchanged (550 -> 550, no new overloads), org_id-referencing functions 79 -> 20.
--
-- DELIBERATELY EXCLUDED (still reference org_id; handled in later migrations before
-- the org_id column is dropped):
--   * sync_org_tenant_key(), sync_integration_conn_org_id()  -- the sync machinery
--   * execute_report_aggregation(...)  -- runtime p_org_column DEFAULT 'org_id' + dynamic SQL
--   * get_executive_kpis(...)          -- org_id refs target materialized views, not base tables
--   * generate_invoice_number(org_id uuid), generate_quote_number(org_id uuid),
--     get_least_busy_agent(org_id uuid), user_role_in(org_id uuid)  -- param literally named org_id


-- public.apply_age_65_auto_cancellation(p_record_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.apply_age_65_auto_cancellation(p_record_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r record;
  v_dob date;
  v_birthday_month date;
  v_count int := 0;
  v_results jsonb := '[]'::jsonb;
BEGIN
  FOR r IN
    SELECT cr.id,
           cr.organization_id,
           cr.title,
           cr.email,
           cr.owner_id,
           cr.advisor_id,
           cr.data->>'date_of_birth' AS dob_text
      FROM public.crm_records cr
      JOIN public.crm_modules m ON m.id = cr.module_id
     WHERE m.key IN ('contacts', 'members')
       AND cr.market_type = 'healthshare'
       AND cr.data ? 'date_of_birth'
       AND cr.data->>'date_of_birth' ~ '^\d{4}-\d{2}-\d{2}'
       AND (cr.status IS NULL OR cr.status NOT IN ('Cancelled', 'Terminated'))
       AND COALESCE((cr.data->>'age_65_cancel_override')::boolean, false) = false
       AND (p_record_id IS NULL OR cr.id = p_record_id)
  LOOP
    BEGIN
      v_dob := substring(r.dob_text from 1 for 10)::date;
    EXCEPTION WHEN OTHERS THEN
      CONTINUE;
    END;

    v_birthday_month := make_date(
      EXTRACT(YEAR FROM v_dob)::int + 65,
      EXTRACT(MONTH FROM v_dob)::int,
      1
    );

    IF v_birthday_month > CURRENT_DATE THEN
      CONTINUE;
    END IF;

    UPDATE public.crm_records
       SET status = 'Cancelled',
           cancellation_date = v_birthday_month,
           data = data || jsonb_build_object(
             'cancellation_date', v_birthday_month::text,
             'cancellation_reason', 'Aged out at 65',
             'auto_cancelled_at', now()::text
           ),
           updated_at = now()
     WHERE id = r.id;

    v_count := v_count + 1;
    v_results := v_results || jsonb_build_object(
      'record_id', r.id,
      'org_id', r.organization_id,
      'member_name', r.title,
      'member_email', r.email,
      'cancellation_date', v_birthday_month,
      'owner_id', r.owner_id
    );
  END LOOP;

  RETURN jsonb_build_object('count', v_count, 'cancelled', v_results);
END;
$function$;

-- public.auto_link_email_thread()  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.auto_link_email_thread()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE
  v_participant record;
  v_contact_id uuid;
BEGIN
  FOR v_participant IN SELECT * FROM jsonb_array_elements(NEW.participants)
  LOOP
    SELECT cr.id INTO v_contact_id
    FROM crm_records cr
    JOIN crm_modules cm ON cr.module_id = cm.id
    WHERE cr.organization_id = NEW.organization_id
      AND cm.key = 'Contacts'
      AND cr.data->>'Email' = v_participant.value->>'email'
    LIMIT 1;

    IF v_contact_id IS NOT NULL THEN
      NEW.linked_contact_id := v_contact_id;
      EXIT;
    END IF;
  END LOOP;

  RETURN NEW;
END;
$function$;

-- public.bulk_auto_merge_duplicates(p_org_id uuid, p_max_per_rule integer)  [MECHANICAL, refs=23, risk=low]
CREATE OR REPLACE FUNCTION public.bulk_auto_merge_duplicates(p_org_id uuid, p_max_per_rule integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_pair             RECORD;
  v_rpc_result       jsonb;

  v_rule1 int := 0;
  v_rule2 int := 0;
  v_rule3 int := 0;
  v_rule4 int := 0;
  v_rule5 int := 0;
  v_errors int := 0;
BEGIN
  IF p_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'p_org_id is required');
  END IF;
  IF p_max_per_rule IS NULL OR p_max_per_rule < 1 OR p_max_per_rule > 5000 THEN
    p_max_per_rule := 1000;
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authenticated');
  END IF;
  IF v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can run bulk merge');
  END IF;
  IF v_actor_org_id <> p_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'You can only run bulk merge for your own organization');
  END IF;

  -- Give ourselves headroom for large orgs. This is the same statement_timeout
  -- escalation the one-shot PIFH migration uses.
  PERFORM set_config('statement_timeout', '10min', true);

  -- ---- Rule 1: linked_member_id collisions -----------------------------
  FOR v_pair IN
    WITH pairs AS (
      SELECT
        (data->>'linked_member_id') AS member_id,
        id, organization_id, module_id, status, updated_at,
        (SELECT count(*) FROM crm_notes  n WHERE n.record_id = crm_records.id) +
        (SELECT count(*) FROM crm_tasks  t WHERE t.record_id = crm_records.id) +
        (SELECT count(*) FROM crm_attachments a WHERE a.record_id = crm_records.id)
          AS history_count
      FROM crm_records
      WHERE organization_id = p_org_id
        AND data ? 'linked_member_id'
        AND data->>'linked_member_id' <> ''
    ),
    grouped AS (
      SELECT member_id, module_id
        FROM pairs GROUP BY member_id, module_id HAVING COUNT(*) > 1
    ),
    ranked AS (
      SELECT p.*,
             ROW_NUMBER() OVER (
               PARTITION BY p.member_id, p.module_id
               ORDER BY p.history_count DESC,
                        (p.status = 'Active') DESC,
                        p.updated_at DESC NULLS LAST
             ) AS rn
        FROM pairs p
        JOIN grouped g ON g.member_id = p.member_id AND g.module_id = p.module_id
    )
    SELECT k.id AS keeper_id, d.id AS duplicate_id
      FROM ranked k
      JOIN ranked d
        ON d.member_id = k.member_id
       AND d.module_id = k.module_id
       AND k.rn = 1
       AND d.rn > 1
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(k.id, d.id)
          AND dd.right_record_id = GREATEST(k.id, d.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule1 := v_rule1 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 2: enrollment-sync twins (zero history) --------------------
  FOR v_pair IN
    WITH sync_twins AS (
      SELECT id, organization_id, module_id, email, phone,
             data->>'first_name' AS first_name,
             data->>'last_name'  AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND data->>'source' = 'enrollment_sync'
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, sync.id AS duplicate_id
      FROM sync_twins sync
      JOIN crm_records real_rec
        ON real_rec.id        <> sync.id
       AND real_rec.organization_id    = sync.organization_id
       AND real_rec.module_id = sync.module_id
       AND (
            (real_rec.email IS NOT NULL AND sync.email IS NOT NULL
               AND LOWER(real_rec.email) = LOWER(sync.email))
         OR (
            real_rec.phone IS NOT NULL AND sync.phone IS NOT NULL
               AND real_rec.phone = sync.phone
               AND sync.first_name IS NOT NULL AND sync.last_name IS NOT NULL
               AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(sync.first_name)
               AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(sync.last_name)
            )
       )
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, sync.id)
          AND dd.right_record_id = GREATEST(real_rec.id, sync.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule2 := v_rule2 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 3: exact email, one side empty -----------------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id, email
        FROM crm_records
       WHERE organization_id = p_org_id
         AND email IS NOT NULL AND email <> ''
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.email IS NOT NULL
       AND LOWER(real_rec.email) = LOWER(empty.email)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule3 := v_rule3 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 4: phone + first + last, one side empty --------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id, phone,
             data->>'first_name' AS first_name,
             data->>'last_name'  AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND phone IS NOT NULL AND phone <> ''
         AND data->>'first_name' IS NOT NULL
         AND data->>'last_name'  IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.phone = empty.phone
       AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(empty.first_name)
       AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(empty.last_name)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule4 := v_rule4 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  -- ---- Rule 5: DOB + first + last, one side empty ----------------------
  FOR v_pair IN
    WITH empties AS (
      SELECT id, organization_id, module_id,
             data->>'date_of_birth' AS dob,
             data->>'first_name'    AS first_name,
             data->>'last_name'     AS last_name
        FROM crm_records
       WHERE organization_id = p_org_id
         AND data->>'date_of_birth' IS NOT NULL
         AND data->>'date_of_birth' <> ''
         AND data->>'first_name' IS NOT NULL
         AND data->>'last_name'  IS NOT NULL
         AND NOT EXISTS (SELECT 1 FROM crm_notes       n WHERE n.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_tasks       t WHERE t.record_id = crm_records.id)
         AND NOT EXISTS (SELECT 1 FROM crm_attachments a WHERE a.record_id = crm_records.id)
    )
    SELECT real_rec.id AS keeper_id, empty.id AS duplicate_id
      FROM empties empty
      JOIN crm_records real_rec
        ON real_rec.id        <> empty.id
       AND real_rec.organization_id    = empty.organization_id
       AND real_rec.module_id = empty.module_id
       AND real_rec.data->>'date_of_birth' = empty.dob
       AND LOWER(COALESCE(real_rec.data->>'first_name','')) = LOWER(empty.first_name)
       AND LOWER(COALESCE(real_rec.data->>'last_name', '')) = LOWER(empty.last_name)
     WHERE NOT EXISTS (
       SELECT 1 FROM crm_duplicate_dismissals dd
        WHERE dd.organization_id = p_org_id
          AND dd.left_record_id  = LEAST(real_rec.id, empty.id)
          AND dd.right_record_id = GREATEST(real_rec.id, empty.id)
     )
     LIMIT p_max_per_rule
  LOOP
    BEGIN
      SELECT merge_crm_records(
        p_keeper_id    => v_pair.keeper_id,
        p_duplicate_id => v_pair.duplicate_id,
        p_user_id      => v_actor_profile_id
      ) INTO v_rpc_result;
      IF (v_rpc_result->>'success')::boolean THEN
        v_rule5 := v_rule5 + 1;
      ELSE
        v_errors := v_errors + 1;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'rule1',   v_rule1,
    'rule2',   v_rule2,
    'rule3',   v_rule3,
    'rule4',   v_rule4,
    'rule5',   v_rule5,
    'errors',  v_errors,
    'total',   v_rule1 + v_rule2 + v_rule3 + v_rule4 + v_rule5
  );
END;
$function$;

-- public.check_approval_required(p_org_id uuid, p_module_id uuid, p_trigger_type text, p_record_data jsonb, p_trigger_context jsonb)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.check_approval_required(p_org_id uuid, p_module_id uuid, p_trigger_type text, p_record_data jsonb, p_trigger_context jsonb DEFAULT '{}'::jsonb)
 RETURNS TABLE(rule_id uuid, process_id uuid, rule_name text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rule RECORD;
  v_cond_array jsonb;
  v_condition RECORD;
  v_logic text;
  v_matches boolean;
  v_field_value jsonb;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN;
  END IF;

  FOR v_rule IN
    SELECT * FROM crm_approval_rules
    WHERE crm_approval_rules.organization_id = p_org_id
      AND crm_approval_rules.module_id = p_module_id
      AND crm_approval_rules.trigger_type = p_trigger_type
      AND crm_approval_rules.is_enabled = true
    ORDER BY priority ASC
  LOOP
    -- conditions is jsonb with {logic, conditions[]} structure
    v_cond_array := COALESCE(v_rule.conditions->'conditions', '[]'::jsonb);
    v_logic := COALESCE(v_rule.conditions->>'logic', 'AND');

    IF jsonb_array_length(v_cond_array) = 0 THEN
      rule_id := v_rule.id;
      process_id := v_rule.process_id;
      rule_name := v_rule.name;
      RETURN NEXT;
      CONTINUE;
    END IF;

    v_matches := CASE WHEN upper(v_logic) = 'AND' THEN true ELSE false END;

    FOR v_condition IN
      SELECT * FROM jsonb_to_recordset(v_cond_array)
      AS x(field text, operator text, value jsonb)
    LOOP
      v_field_value := p_record_data->v_condition.field;

      DECLARE
        v_cond_met boolean := false;
      BEGIN
        CASE v_condition.operator
          WHEN 'equals' THEN
            v_cond_met := v_field_value = v_condition.value;
          WHEN 'not_equals' THEN
            v_cond_met := v_field_value != v_condition.value;
          WHEN 'greater_than' THEN
            v_cond_met := (v_field_value::text)::numeric > (v_condition.value::text)::numeric;
          WHEN 'less_than' THEN
            v_cond_met := (v_field_value::text)::numeric < (v_condition.value::text)::numeric;
          WHEN 'contains' THEN
            v_cond_met := v_field_value::text ILIKE '%' || (v_condition.value#>>'{}') || '%';
          WHEN 'in' THEN
            v_cond_met := v_field_value <@ v_condition.value;
          WHEN 'changed' THEN
            v_cond_met := p_trigger_context ? v_condition.field;
          ELSE
            v_cond_met := false;
        END CASE;

        IF upper(v_logic) = 'AND' AND NOT v_cond_met THEN
          v_matches := false;
          EXIT;
        ELSIF upper(v_logic) = 'OR' AND v_cond_met THEN
          v_matches := true;
          EXIT;
        END IF;
      END;
    END LOOP;

    IF v_matches THEN
      rule_id := v_rule.id;
      process_id := v_rule.process_id;
      rule_name := v_rule.name;
      RETURN NEXT;
    END IF;
  END LOOP;
END;
$function$;

-- public.check_approval_required(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_data jsonb)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.check_approval_required(p_org_id uuid, p_entity_type text, p_entity_id uuid, p_action text, p_data jsonb)
 RETURNS TABLE(required boolean, rule_id uuid, rule_name text)
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_rule record;
BEGIN
  FOR v_rule IN
    SELECT agr.id, agr.name, agr.trigger_conditions
    FROM approval_guard_rules agr
    WHERE agr.organization_id = p_org_id
      AND agr.entity_type = p_entity_type
      AND agr.is_active = true
    ORDER BY agr.priority DESC
  LOOP
    IF p_data ? (v_rule.trigger_conditions->>'field') THEN
      required := true;
      rule_id := v_rule.id;
      rule_name := v_rule.name;
      RETURN NEXT;
      RETURN;
    END IF;
  END LOOP;

  required := false;
  RETURN NEXT;
END;
$function$;

-- public.check_crm_duplicate(p_org_id uuid, p_module_id uuid, p_email text, p_phone text, p_exclude_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.check_crm_duplicate(p_org_id uuid, p_module_id uuid, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_exclude_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(id uuid, title text, email text, phone text, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT r.id, r.title, r.email, r.phone, r.status, r.created_at
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.module_id = p_module_id
    AND (p_exclude_id IS NULL OR r.id != p_exclude_id)
    AND (
      -- Primary: match by email (case-insensitive)
      (p_email IS NOT NULL AND p_email != '' AND LOWER(r.email) = LOWER(p_email))
      OR
      -- Fallback: match by phone only when no email provided
      (
        (p_email IS NULL OR p_email = '')
        AND p_phone IS NOT NULL AND p_phone != ''
        AND r.phone = p_phone
      )
    )
  LIMIT 5;
END;
$function$;

-- public.convert_lead_to_contact(p_lead_record_id uuid, p_user_id uuid, p_merge_into_contact_id uuid)  [WRITES_ORG_ID, refs=7, risk=low]
CREATE OR REPLACE FUNCTION public.convert_lead_to_contact(p_lead_record_id uuid, p_user_id uuid, p_merge_into_contact_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lead_record        crm_records%ROWTYPE;
  v_org_id             uuid;
  v_leads_module_id    uuid;
  v_contacts_module_id uuid;
  v_lead_data          jsonb;
  v_contact_data       jsonb;
  v_contact_title      text;
  v_new_contact_id     uuid;
  v_existing_contact_id uuid;
  v_existing_data      jsonb;
BEGIN
  SELECT * INTO v_lead_record FROM crm_records WHERE id = p_lead_record_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lead record not found');
  END IF;

  v_org_id    := v_lead_record.organization_id;
  v_lead_data := COALESCE(v_lead_record.data, '{}'::jsonb);

  SELECT m.id INTO v_leads_module_id
  FROM crm_modules m
  WHERE m.id = v_lead_record.module_id AND m.key = 'leads';

  IF v_leads_module_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Record does not belong to a Leads module');
  END IF;

  IF v_lead_record.status = 'Converted'
     OR v_lead_data->>'is_converted' = 'true' THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'This lead has already been converted',
      'converted_contact_id', v_lead_data->>'converted_contact_id'
    );
  END IF;

  SELECT m.id INTO v_contacts_module_id
  FROM crm_modules m
  WHERE m.organization_id = v_org_id AND m.key = 'contacts' AND m.is_enabled = true
  LIMIT 1;

  IF v_contacts_module_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Contacts module not found or is disabled');
  END IF;

  v_contact_data := jsonb_build_object(
    'salutation',       v_lead_data->>'salutation',
    'first_name',       v_lead_data->>'first_name',
    'last_name',        v_lead_data->>'last_name',
    'email',            v_lead_data->>'email',
    'phone',            v_lead_data->>'phone',
    'mobile',           v_lead_data->>'mobile',
    'date_of_birth',    v_lead_data->>'date_of_birth',
    'lead_source',      v_lead_data->>'lead_source',
    'owner_id',         v_lead_data->>'owner_id',
    'coverage_option',  v_lead_data->>'coverage_option',
    'spouse',           v_lead_data->>'spouse',
    'spouse_dob',       v_lead_data->>'spouse_dob',
    'child_1',          v_lead_data->>'child_1',
    'child_1_dob',      v_lead_data->>'child_1_dob',
    'child_2',          v_lead_data->>'child_2',
    'child_2_dob',      v_lead_data->>'child_2_dob',
    'child_3',          v_lead_data->>'child_3',
    'child_3_dob',      v_lead_data->>'child_3_dob',
    'child_4',          v_lead_data->>'child_4',
    'child_4_dob',      v_lead_data->>'child_4_dob',
    'child_5',          v_lead_data->>'child_5',
    'child_5_dob',      v_lead_data->>'child_5_dob',
    'referring_member', v_lead_data->>'referring_member',
    'email_opt_out',    v_lead_data->>'email_opt_out',
    'tag',              v_lead_data->>'tag',
    'company_association', v_lead_data->>'company',
    'mailing_street',   v_lead_data->>'street',
    'mailing_city',     v_lead_data->>'city',
    'mailing_state',    v_lead_data->>'state',
    'mailing_zip',      v_lead_data->>'zip_code',
    'product',          v_lead_data->>'product_type',
    'contact_status',   'Active',
    'converted_from_lead_id',  p_lead_record_id::text
  );

  SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb)
    INTO v_contact_data
    FROM jsonb_each(v_contact_data) AS x(k, v)
   WHERE v IS DISTINCT FROM 'null'::jsonb
     AND v::text != '""';

  v_contact_title := TRIM(
    COALESCE(v_lead_data->>'first_name', '') || ' ' || COALESCE(v_lead_data->>'last_name', '')
  );
  IF v_contact_title = '' THEN
    v_contact_title := 'Converted Lead';
  END IF;

  IF p_merge_into_contact_id IS NOT NULL THEN
    SELECT id, COALESCE(data, '{}'::jsonb) INTO v_new_contact_id, v_existing_data
    FROM crm_records
    WHERE id = p_merge_into_contact_id
      AND organization_id = v_org_id
      AND module_id = v_contacts_module_id;

    IF v_new_contact_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'Target contact not found');
    END IF;

    UPDATE crm_records
    SET data = (
      SELECT COALESCE(jsonb_object_agg(
        COALESCE(ek.key, nk.key),
        COALESCE(ek.value, nk.value)
      ), '{}'::jsonb)
      FROM jsonb_each(v_existing_data) ek
      FULL OUTER JOIN jsonb_each(v_contact_data) nk ON ek.key = nk.key
      WHERE COALESCE(ek.value, nk.value) IS DISTINCT FROM 'null'::jsonb
    ),
    email = COALESCE(NULLIF(email, ''), v_lead_record.email),
    phone = COALESCE(NULLIF(phone, ''), v_lead_record.phone),
    updated_at = now()
    WHERE id = p_merge_into_contact_id;

  ELSE
    IF v_lead_record.email IS NOT NULL AND v_lead_record.email != '' THEN
      SELECT id INTO v_existing_contact_id
      FROM crm_records
      WHERE organization_id = v_org_id
        AND module_id = v_contacts_module_id
        AND LOWER(email) = LOWER(v_lead_record.email)
      LIMIT 1;

      IF v_existing_contact_id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'success', false,
          'error', 'A contact with email ' || v_lead_record.email || ' already exists',
          'existing_contact_id', v_existing_contact_id
        );
      END IF;
    END IF;

    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, created_by, created_at, updated_at
    ) VALUES (
      v_org_id,
      v_contacts_module_id,
      v_lead_record.owner_id,
      v_contact_title,
      'Active',
      v_lead_record.email,
      v_lead_record.phone,
      v_contact_data,
      p_user_id,
      now(),
      now()
    )
    RETURNING id INTO v_new_contact_id;
  END IF;

  -- Move CRM notes onto the new/merged contact.
  UPDATE crm_notes
     SET record_id = v_new_contact_id
   WHERE record_id = p_lead_record_id;

  -- ── THE FIX ────────────────────────────────────────────────────────────
  -- public.notes.record_id was changed from text → uuid; the previous
  -- `::text` casts now compare uuid against text and Postgres rejects it
  -- (`42883: operator does not exist: uuid = text`). Drop the casts.
  -- ──────────────────────────────────────────────────────────────────────
  BEGIN
    UPDATE notes
       SET record_id = v_new_contact_id
     WHERE record_id = p_lead_record_id;
  EXCEPTION WHEN undefined_table THEN
    -- Legacy `notes` table not present in this DB — skip silently.
    NULL;
  END;

  INSERT INTO crm_record_links (
    organization_id, source_record_id, target_record_id,
    link_type, is_primary, created_by
  ) VALUES (
    v_org_id, p_lead_record_id, v_new_contact_id,
    'lead_to_contact', true, p_user_id
  );

  UPDATE crm_records
  SET status = 'Converted',
      data = jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(
              COALESCE(data, '{}'::jsonb),
              '{is_converted}', 'true'::jsonb
            ),
            '{converted_date}', to_jsonb(to_char(now(), 'YYYY-MM-DD'))
          ),
          '{converted_contact_id}', to_jsonb(v_new_contact_id::text)
        ),
        '{lead_status}', '"Converted"'::jsonb
      ),
      updated_at = now()
  WHERE id = p_lead_record_id;

  INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_org_id,
    p_user_id,
    'lead',
    p_lead_record_id,
    'update',
    jsonb_build_object(
      'action', CASE WHEN p_merge_into_contact_id IS NOT NULL THEN 'merge_into_contact' ELSE 'convert_to_contact' END,
      'converted_contact_id', v_new_contact_id,
      'contact_title', v_contact_title,
      'merged', p_merge_into_contact_id IS NOT NULL,
      'converted_at', now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'contact_id', v_new_contact_id,
    'contact_title', v_contact_title,
    'lead_id', p_lead_record_id,
    'message', CASE
      WHEN p_merge_into_contact_id IS NOT NULL THEN 'Lead merged into existing contact successfully'
      ELSE 'Lead converted to contact successfully'
    END
  );

EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;

-- public.convert_lead_to_member(p_lead_record_id uuid, p_user_id uuid)  [WRITES_ORG_ID, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.convert_lead_to_member(p_lead_record_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lead_record crm_records%ROWTYPE;
  v_org_id uuid;
  v_new_member_id uuid;
BEGIN
  SELECT * INTO v_lead_record
  FROM crm_records
  WHERE id = p_lead_record_id;

  IF v_lead_record.id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Lead record not found');
  END IF;

  v_org_id := v_lead_record.organization_id;

  IF v_lead_record.email IS NOT NULL THEN
    SELECT id INTO v_new_member_id
    FROM members
    WHERE email = v_lead_record.email
      AND organization_id = v_org_id
    LIMIT 1;
  END IF;

  IF v_new_member_id IS NULL THEN
    INSERT INTO members (
      organization_id, first_name, last_name, email, phone,
      status, created_at, updated_at
    ) VALUES (
      v_org_id,
      v_lead_record.data->>'first_name',
      v_lead_record.data->>'last_name',
      v_lead_record.email,
      v_lead_record.phone,
      'Active', now(), now()
    )
    RETURNING id INTO v_new_member_id;
  END IF;

  UPDATE crm_records
  SET status = 'Converted',
      data = jsonb_set(
        jsonb_set(
          COALESCE(data, '{}'::jsonb),
          '{lead_status}', '"Converted"'::jsonb
        ),
        '{converted_member_id}', to_jsonb(v_new_member_id::text)
      ),
      updated_at = now()
  WHERE id = p_lead_record_id;

  -- Fixed: use correct crm_audit_log columns (actor_id, entity_id, diff)
  INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_org_id,
    p_user_id,
    'lead',
    p_lead_record_id,
    'update',
    jsonb_build_object(
      'converted_to_member_id', v_new_member_id,
      'converted_at', now()
    )
  );

  RETURN jsonb_build_object(
    'success', true,
    'member_id', v_new_member_id,
    'lead_id', p_lead_record_id,
    'message', 'Lead converted to member successfully'
  );
EXCEPTION WHEN OTHERS THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;

-- public.crm_phone_lookup(p_org_id uuid, p_query text, p_module_key text, p_limit integer)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.crm_phone_lookup(p_org_id uuid, p_query text, p_module_key text DEFAULT NULL::text, p_limit integer DEFAULT 25)
 RETURNS TABLE(id uuid, title text, email text, phone text, status text, module_id uuid, data jsonb, module_key text, module_name text, module_name_plural text, match_type text, rank real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_digits text := regexp_replace(coalesce(p_query, ''), '\D', '', 'g');
  v_tail   text := right(v_digits, 10);
BEGIN
  IF length(v_digits) < 4 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    r.id,
    r.title,
    r.email,
    r.phone,
    r.status,
    r.module_id,
    r.data,
    m.key          AS module_key,
    m.name         AS module_name,
    m.name_plural  AS module_name_plural,
    'exact'::text  AS match_type,
    CASE
      WHEN regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits THEN 2.50::real
      WHEN length(v_tail) = 10
        AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail THEN 2.30::real
      WHEN regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%' THEN 1.95::real
      ELSE 1.50::real
    END AS rank
  FROM public.crm_records r
  JOIN public.crm_modules m ON m.id = r.module_id
  WHERE r.organization_id = p_org_id
    AND (p_module_key IS NULL OR m.key = p_module_key)
    AND (
      regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%'
      OR (
        length(v_tail) = 10
        AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail
      )
    )
  ORDER BY rank DESC, r.updated_at DESC NULLS LAST, r.id
  LIMIT GREATEST(p_limit, 1);
END;
$function$;

-- public.crm_smart_search(p_org_id uuid, p_query text, p_module_key text, p_limit integer, p_similarity_threshold real)  [MECHANICAL, refs=5, risk=low]
CREATE OR REPLACE FUNCTION public.crm_smart_search(p_org_id uuid, p_query text, p_module_key text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_similarity_threshold real DEFAULT 0.18)
 RETURNS TABLE(id uuid, title text, email text, phone text, status text, module_id uuid, data jsonb, module_key text, module_name text, module_name_plural text, match_type text, rank real)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
#variable_conflict use_column
DECLARE
  v_query        text := btrim(coalesce(p_query, ''));
  v_query_lower  text;
  v_clean        text;
  v_words        text[];
  v_tsquery_and  text;
  v_tsquery_or   text;
  v_digits       text;
  v_tail         text;
  v_word_len     int;
  v_thr          real := LEAST(GREATEST(p_similarity_threshold, 0.05::real), 0.9::real);
  v_cte_cap      int := 200;
BEGIN
  IF length(v_query) = 0 THEN
    RETURN;
  END IF;

  v_query_lower := lower(v_query);
  v_clean := lower(regexp_replace(v_query, '[^a-z0-9 ]', ' ', 'gi'));
  v_words := regexp_split_to_array(btrim(v_clean), '\s+');
  v_word_len := cardinality(v_words);

  SELECT string_agg(w || ':*', ' & ')
    INTO v_tsquery_and
    FROM unnest(v_words) AS w
   WHERE length(w) >= 2;

  SELECT string_agg(w || ':*', ' | ')
    INTO v_tsquery_or
    FROM unnest(v_words) AS w
   WHERE length(w) >= 2;

  v_digits := regexp_replace(v_query, '\D', '', 'g');
  v_tail   := right(v_digits, 10);

  RETURN QUERY
  WITH
  exact_hits AS (
    SELECT
      r.id,
      CASE
        WHEN lower(trim(coalesce(r.email, ''))) = v_query_lower THEN 2.85::real
        WHEN lower(trim(coalesce(r.title, ''))) = v_query_lower THEN 2.55::real
        WHEN length(v_digits) >= 7
          AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits THEN 2.45::real
        WHEN length(v_tail) = 10
          AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail THEN 2.30::real
        WHEN strpos(v_query_lower, '@') > 0
          AND lower(coalesce(r.email, '')) LIKE '%' || v_query_lower || '%' THEN 2.35::real
        ELSE 2.00::real
      END AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND (
        lower(trim(coalesce(r.email, ''))) = v_query_lower
        OR lower(trim(coalesce(r.title, ''))) = v_query_lower
        OR (
          length(v_digits) >= 7
          AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') = v_digits
        )
        OR (
          length(v_tail) = 10
          AND right(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), 10) = v_tail
        )
        OR (
          strpos(v_query_lower, '@') > 0
          AND lower(coalesce(r.email, '')) LIKE '%' || v_query_lower || '%'
        )
      )
    LIMIT v_cte_cap
  ),
  fts_and_hits AS (
    SELECT
      r.id,
      ts_rank_cd(r.search, to_tsquery('english', v_tsquery_and)) + 1.05::real AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND v_tsquery_and IS NOT NULL
      AND r.search @@ to_tsquery('english', v_tsquery_and)
    LIMIT v_cte_cap
  ),
  fts_or_hits AS (
    SELECT
      r.id,
      ts_rank_cd(r.search, to_tsquery('english', v_tsquery_or)) * 0.55::real + 0.72::real AS rank,
      'fuzzy'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND v_tsquery_or IS NOT NULL
      AND v_word_len > 1
      AND r.search @@ to_tsquery('english', v_tsquery_or)
      AND NOT (v_tsquery_and IS NOT NULL AND r.search @@ to_tsquery('english', v_tsquery_and))
    LIMIT v_cte_cap
  ),
  fuzzy_hits AS (
    SELECT
      r.id,
      GREATEST(
        similarity(coalesce(r.title, ''), v_query),
        similarity(coalesce(r.email, ''), v_query),
        CASE
          WHEN length(v_digits) >= 4
          THEN similarity(regexp_replace(coalesce(r.phone, ''), '\D', '', 'g'), v_digits)
          ELSE 0::real
        END,
        similarity(
          coalesce(r.data->>'first_name', '') || ' ' ||
          coalesce(r.data->>'last_name', ''),
          v_query
        )
      )::real AS rank,
      'fuzzy'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND (
        r.title % v_query
        OR r.email % v_query
        OR r.phone % v_query
        OR (
          coalesce(r.data->>'first_name', '') || ' ' ||
          coalesce(r.data->>'last_name', '')
        ) % v_query
      )
    LIMIT v_cte_cap
  ),
  phone_hits AS (
    SELECT
      r.id,
      1.85::real AS rank,
      'exact'::text AS match_type
    FROM public.crm_records r
    WHERE r.organization_id = p_org_id
      AND length(v_digits) >= 4
      AND regexp_replace(coalesce(r.phone, ''), '\D', '', 'g') LIKE '%' || v_digits || '%'
    LIMIT v_cte_cap
  ),
  combined AS (
    SELECT
      h.id,
      MAX(h.rank) AS rank,
      CASE
        WHEN bool_or(h.match_type = 'exact') THEN 'exact'
        ELSE 'fuzzy'
      END AS match_type
    FROM (
      SELECT * FROM exact_hits
      UNION ALL
      SELECT * FROM fts_and_hits
      UNION ALL
      SELECT * FROM fts_or_hits
      UNION ALL
      SELECT * FROM fuzzy_hits  WHERE rank >= v_thr
      UNION ALL
      SELECT * FROM phone_hits
    ) h
    GROUP BY h.id
  )
  SELECT
    r.id,
    r.title,
    r.email,
    r.phone,
    r.status,
    r.module_id,
    r.data,
    m.key          AS module_key,
    m.name         AS module_name,
    m.name_plural  AS module_name_plural,
    c.match_type,
    c.rank
  FROM combined c
  JOIN public.crm_records r ON r.id = c.id
  JOIN public.crm_modules m ON m.id = r.module_id
  WHERE (p_module_key IS NULL OR m.key = p_module_key)
  -- Deterministic ordering: rank desc, then updated_at desc, then id as a
  -- final tiebreaker so the same query always returns the same N records.
  -- Without the `r.id` term the same query was returning different 25-row
  -- subsets of common-name buckets (e.g. all 104 PIFH "Johnson" records
  -- share an `updated_at` from the org realignment migration), which made
  -- "Jake Johnson" appear and disappear between keystrokes.
  ORDER BY c.rank DESC, r.updated_at DESC NULLS LAST, r.id
  LIMIT GREATEST(p_limit, 1);
END;
$function$;

-- public.deduplicate_contacts()  [MECHANICAL, refs=7, risk=low]
CREATE OR REPLACE FUNCTION public.deduplicate_contacts()
 RETURNS TABLE(duplicates_found integer, records_merged integer, records_deleted integer, name_phone_duplicates_found integer, name_phone_deleted integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_module_id uuid;
  v_dup RECORD;
  v_keeper_id uuid;
  v_dupe_rec RECORD;
  v_duplicates_found int := 0;
  v_records_merged int := 0;
  v_records_deleted int := 0;
  v_np_duplicates_found int := 0;
  v_np_deleted int := 0;
BEGIN
  SELECT id INTO v_org_id FROM organizations LIMIT 1;
  SELECT id INTO v_module_id FROM crm_modules
  WHERE organization_id = v_org_id AND key = 'contacts';

  -- Phase 1: Deduplicate by email
  FOR v_dup IN
    SELECT LOWER(email) AS norm_email, COUNT(*) AS cnt
    FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND email IS NOT NULL AND email != ''
    GROUP BY LOWER(email) HAVING COUNT(*) > 1
    ORDER BY COUNT(*) DESC
  LOOP
    v_duplicates_found := v_duplicates_found + 1;
    SELECT id INTO v_keeper_id FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND LOWER(email) = v_dup.norm_email
    ORDER BY updated_at DESC LIMIT 1;

    FOR v_dupe_rec IN
      SELECT id, data FROM crm_records
      WHERE organization_id = v_org_id AND module_id = v_module_id
        AND LOWER(email) = v_dup.norm_email AND id != v_keeper_id
      ORDER BY updated_at DESC
    LOOP
      UPDATE crm_records SET
        data = (
          SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
          FROM jsonb_each(
            COALESCE(v_dupe_rec.data, '{}'::jsonb) ||
            COALESCE((SELECT data FROM crm_records WHERE id = v_keeper_id), '{}'::jsonb)
          )
          WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb
        ),
        updated_at = now()
      WHERE id = v_keeper_id;
      v_records_merged := v_records_merged + 1;
      DELETE FROM crm_records WHERE id = v_dupe_rec.id;
      v_records_deleted := v_records_deleted + 1;
    END LOOP;
  END LOOP;

  -- Phase 2: Deduplicate by name + phone
  FOR v_dup IN
    SELECT LOWER(data->>'first_name') AS norm_first,
           LOWER(data->>'last_name') AS norm_last,
           phone AS norm_phone, COUNT(*) AS cnt
    FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND data->>'first_name' IS NOT NULL AND data->>'last_name' IS NOT NULL
      AND phone IS NOT NULL AND phone != ''
    GROUP BY LOWER(data->>'first_name'), LOWER(data->>'last_name'), phone
    HAVING COUNT(*) > 1
    ORDER BY COUNT(*) DESC
  LOOP
    v_np_duplicates_found := v_np_duplicates_found + 1;
    SELECT id INTO v_keeper_id FROM crm_records
    WHERE organization_id = v_org_id AND module_id = v_module_id
      AND LOWER(data->>'first_name') = v_dup.norm_first
      AND LOWER(data->>'last_name') = v_dup.norm_last
      AND phone = v_dup.norm_phone
    ORDER BY updated_at DESC LIMIT 1;

    FOR v_dupe_rec IN
      SELECT id, data FROM crm_records
      WHERE organization_id = v_org_id AND module_id = v_module_id
        AND LOWER(data->>'first_name') = v_dup.norm_first
        AND LOWER(data->>'last_name') = v_dup.norm_last
        AND phone = v_dup.norm_phone AND id != v_keeper_id
      ORDER BY updated_at DESC
    LOOP
      UPDATE crm_records SET
        data = (
          SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
          FROM jsonb_each(
            COALESCE(v_dupe_rec.data, '{}'::jsonb) ||
            COALESCE((SELECT data FROM crm_records WHERE id = v_keeper_id), '{}'::jsonb)
          )
          WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb
        ),
        updated_at = now()
      WHERE id = v_keeper_id;
      DELETE FROM crm_records WHERE id = v_dupe_rec.id;
      v_np_deleted := v_np_deleted + 1;
    END LOOP;
  END LOOP;

  RETURN QUERY SELECT v_duplicates_found, v_records_merged, v_records_deleted, v_np_duplicates_found, v_np_deleted;
END;
$function$;

-- public.dismiss_duplicate_pair(p_a_id uuid, p_b_id uuid, p_reason text)  [WRITES_ORG_ID, refs=5, risk=low]
CREATE OR REPLACE FUNCTION public.dismiss_duplicate_pair(p_a_id uuid, p_b_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_left_id          uuid;
  v_right_id         uuid;
  v_a_org_id         uuid;
  v_b_org_id         uuid;
BEGIN
  IF p_a_id IS NULL OR p_b_id IS NULL OR p_a_id = p_b_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Two different record ids are required');
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL OR v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can dismiss duplicate pairs');
  END IF;

  SELECT organization_id INTO v_a_org_id FROM public.crm_records WHERE id = p_a_id;
  SELECT organization_id INTO v_b_org_id FROM public.crm_records WHERE id = p_b_id;

  IF v_a_org_id IS NULL OR v_b_org_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'One or both records do not exist');
  END IF;

  IF v_a_org_id <> v_actor_org_id OR v_b_org_id <> v_actor_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records must belong to your organization');
  END IF;

  IF v_a_org_id <> v_b_org_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records must belong to the same organization');
  END IF;

  v_left_id  := LEAST(p_a_id, p_b_id);
  v_right_id := GREATEST(p_a_id, p_b_id);

  INSERT INTO public.crm_duplicate_dismissals (organization_id, left_record_id, right_record_id, dismissed_by, reason)
  VALUES (v_actor_org_id, v_left_id, v_right_id, v_actor_profile_id, NULLIF(TRIM(p_reason), ''))
  ON CONFLICT (organization_id, left_record_id, right_record_id) DO UPDATE
    SET dismissed_by = EXCLUDED.dismissed_by,
        dismissed_at = now(),
        reason       = EXCLUDED.reason;

  INSERT INTO public.crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
  VALUES (
    v_actor_org_id,
    v_actor_profile_id,
    'record',
    v_left_id,
    'duplicate_dismissed',
    jsonb_build_object(
      'left_id',  v_left_id,
      'right_id', v_right_id,
      'reason',   NULLIF(TRIM(p_reason), '')
    )
  );

  RETURN jsonb_build_object('success', true, 'left_id', v_left_id, 'right_id', v_right_id);
END;
$function$;

-- public.emit_integration_event(p_org_id uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_previous_state jsonb, p_source text)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.emit_integration_event(p_org_id uuid, p_event_type text, p_entity_type text, p_entity_id uuid, p_payload jsonb, p_previous_state jsonb DEFAULT NULL::jsonb, p_source text DEFAULT 'internal'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_event_id uuid;
BEGIN
  INSERT INTO integration_events (
    organization_id, event_type, entity_type, entity_id, payload, previous_state, source
  ) VALUES (
    p_org_id, p_event_type, p_entity_type, p_entity_id, p_payload, p_previous_state, p_source
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$;

-- public.ensure_single_default_sender()  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.ensure_single_default_sender()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_default = true THEN
    UPDATE email_sender_addresses
    SET is_default = false, updated_at = now()
    WHERE organization_id = NEW.organization_id
      AND id != NEW.id
      AND is_default = true;
  END IF;
  RETURN NEW;
END;
$function$;

-- public.execute_report_query(p_org_id uuid, p_primary_module_id uuid, p_related_modules text, p_columns text, p_filters text, p_filter_logic text, p_limit integer, p_offset integer)  [PARAM_NAMED_ORG_ID, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.execute_report_query(p_org_id uuid, p_primary_module_id uuid, p_related_modules text DEFAULT '[]'::text, p_columns text DEFAULT '[]'::text, p_filters text DEFAULT '[]'::text, p_filter_logic text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_related jsonb;
  v_result jsonb;
  v_sql text;
  v_where text := '';
  v_joins text := '';
  v_select text := '';
  v_rm record;
  v_i int := 0;
  v_alias text;
  v_mod_id uuid;
  v_join_type text;
BEGIN
  v_related := p_related_modules::jsonb;

  -- Build base SELECT
  v_select := 'SELECT p.id, p.data AS primary_data, p.created_at, p.updated_at';

  -- Build JOINs for each related module
  FOR v_rm IN SELECT * FROM jsonb_array_elements(v_related)
  LOOP
    v_i := v_i + 1;
    v_alias := 'r' || v_i;
    v_mod_id := (v_rm.value->>'module_id')::uuid;
    v_join_type := COALESCE(v_rm.value->>'join_type', 'inclusive');

    -- Add related module data to SELECT
    v_select := v_select || format(
      ', %I.data AS %s_data',
      v_alias,
      COALESCE(v_rm.value->>'module_key', 'related' || v_i)
    );

    -- Build JOIN via crm_record_links
    IF v_join_type = 'exclusive' THEN
      v_joins := v_joins || format(
        ' INNER JOIN crm_record_links %s_link ON (%s_link.source_record_id = p.id OR %s_link.target_record_id = p.id)'
        || ' INNER JOIN crm_records %I ON (%I.id = CASE WHEN %s_link.source_record_id = p.id THEN %s_link.target_record_id ELSE %s_link.source_record_id END'
        || ' AND %I.module_id = %L AND %I.organization_id = %L)',
        v_alias, v_alias, v_alias,
        v_alias, v_alias, v_alias, v_alias, v_alias,
        v_alias, v_mod_id, v_alias, p_org_id
      );
    ELSE
      v_joins := v_joins || format(
        ' LEFT JOIN crm_record_links %s_link ON (%s_link.source_record_id = p.id OR %s_link.target_record_id = p.id)'
        || ' LEFT JOIN crm_records %I ON (%I.id = CASE WHEN %s_link.source_record_id = p.id THEN %s_link.target_record_id ELSE %s_link.source_record_id END'
        || ' AND %I.module_id = %L AND %I.organization_id = %L)',
        v_alias, v_alias, v_alias,
        v_alias, v_alias, v_alias, v_alias, v_alias,
        v_alias, v_mod_id, v_alias, p_org_id
      );
    END IF;
  END LOOP;

  -- Build WHERE clause
  v_where := format(' WHERE p.organization_id = %L AND p.module_id = %L', p_org_id, p_primary_module_id);

  -- Assemble final query
  v_sql := v_select
    || ' FROM crm_records p'
    || v_joins
    || v_where
    || ' ORDER BY p.created_at DESC'
    || format(' LIMIT %s OFFSET %s', p_limit, p_offset);

  -- Execute and return as JSONB array
  EXECUTE format('SELECT COALESCE(jsonb_agg(row_to_json(t)), ''[]''::jsonb) FROM (%s) t', v_sql)
    INTO v_result;

  RETURN v_result;
END;
$function$;

-- public.filter_records_by_system_preset(p_module_id uuid, p_preset text, p_user_profile_id uuid, p_value text)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.filter_records_by_system_preset(p_module_id uuid, p_preset text, p_user_profile_id uuid DEFAULT NULL::uuid, p_value text DEFAULT NULL::text)
 RETURNS SETOF uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Authorization: caller must belong to the org that owns this module
  IF NOT EXISTS (
    SELECT 1 FROM crm_modules m
    JOIN profiles p ON p.organization_id = m.organization_id
    WHERE m.id = p_module_id
      AND p.user_id = auth.uid()
  ) THEN
    RETURN;
  END IF;

  CASE p_preset
    -- ══════════════════════════════════════════════════════════
    -- BUSINESS LANE FILTERS (query columns on crm_records)
    -- ══════════════════════════════════════════════════════════
    WHEN 'healthshare_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.market_type = 'healthshare';

    WHEN 'insurance_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.market_type = 'traditional_insurance';

    WHEN 'unclassified_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (r.market_type IS NULL OR r.market_type = 'unknown');

    WHEN 'needs_review_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.normalization_status = 'needs_review';

    -- ══════════════════════════════════════════════════════════
    -- OWNER FILTER (from Filter by Owner combobox)
    -- ══════════════════════════════════════════════════════════
    WHEN 'owner_is' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (
            r.owner_id = p_value::uuid
            OR r.canonical_advisor_id = p_value::uuid
          );

    -- ══════════════════════════════════════════════════════════
    -- ACTIVITY / ENGAGEMENT FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'touched_records' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id)
               OR EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id));

    WHEN 'untouched_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND NOT EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id)
          AND NOT EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);

    WHEN 'my_records' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.owner_id = p_user_profile_id;

    WHEN 'unassigned' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id AND r.owner_id IS NULL;

    -- ══════════════════════════════════════════════════════════
    -- DATE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'created_today' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.created_at >= date_trunc('day', now())
          AND r.created_at < date_trunc('day', now()) + interval '1 day';

    WHEN 'created_this_week' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.created_at >= date_trunc('week', now())
          AND r.created_at < date_trunc('week', now()) + interval '1 week';

    WHEN 'modified_today' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.updated_at >= date_trunc('day', now())
          AND r.updated_at < date_trunc('day', now()) + interval '1 day';

    WHEN 'modified_this_week' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.updated_at >= date_trunc('week', now())
          AND r.updated_at < date_trunc('week', now()) + interval '1 week';

    -- ══════════════════════════════════════════════════════════
    -- TASK / NOTE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'has_activities' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id);

    WHEN 'no_activities' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND NOT EXISTS (SELECT 1 FROM crm_tasks t WHERE t.record_id = r.id);

    WHEN 'has_notes' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (SELECT 1 FROM crm_notes n WHERE n.record_id = r.id);

    WHEN 'has_open_tasks' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (
            SELECT 1 FROM crm_tasks t
            WHERE t.record_id = r.id AND t.status NOT IN ('completed', 'cancelled')
          );

    WHEN 'has_overdue_tasks' THEN
      RETURN QUERY
        SELECT DISTINCT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND EXISTS (
            SELECT 1 FROM crm_tasks t
            WHERE t.record_id = r.id
              AND t.status NOT IN ('completed', 'cancelled')
              AND t.due_at IS NOT NULL AND t.due_at < now()
          );

    -- ══════════════════════════════════════════════════════════
    -- RECORD STATE FILTERS
    -- ══════════════════════════════════════════════════════════
    WHEN 'locked' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND (r.data->>'is_locked')::boolean = true;

    -- ══════════════════════════════════════════════════════════
    -- CAMPAIGN / CADENCE / COMMUNICATION FILTERS
    -- These check for existence of related campaign/cadence data
    -- ══════════════════════════════════════════════════════════
    WHEN 'campaigns' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'campaign_source' IS NOT NULL;

    WHEN 'cadences' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'cadence_id' IS NOT NULL;

    WHEN 'chats' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'chat_count' IS NOT NULL
          AND (r.data->>'chat_count')::int > 0;

    WHEN 'website_activity' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'website_visits' IS NOT NULL
          AND (r.data->>'website_visits')::int > 0;

    -- ══════════════════════════════════════════════════════════
    -- VALUE-BASED FILTERS (use p_value parameter)
    -- ══════════════════════════════════════════════════════════
    WHEN 'record_action' THEN
      RETURN QUERY
        SELECT DISTINCT a.record_id FROM crm_audit_log a
        JOIN crm_records r ON r.id = a.record_id
        WHERE r.module_id = p_module_id AND a.action = COALESCE(p_value, 'update');

    WHEN 'related_records_action' THEN
      RETURN QUERY
        SELECT DISTINCT a.record_id FROM crm_audit_log a
        JOIN crm_records r ON r.id = a.record_id
        WHERE r.module_id = p_module_id
          AND a.action = COALESCE(p_value, 'update')
          AND a.changes->>'related' IS NOT NULL;

    WHEN 'scoring_rules' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'score' IS NOT NULL
          AND (r.data->>'score')::int >= COALESCE(p_value::int, 0);

    WHEN 'latest_email_status' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'latest_email_status' = COALESCE(p_value, 'sent');

    WHEN 'attended_by' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'attended_by' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'browser' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'browser' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'operating_system' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'operating_system' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'portal_name' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'portal_name' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'search_engine' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'search_engine' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'referrer' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'referrer' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'time_spent_minutes' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'time_spent_minutes' IS NOT NULL
          AND (r.data->>'time_spent_minutes')::numeric >= COALESCE(p_value::numeric, 0);

    WHEN 'time_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'time_visited' IS NOT NULL
          AND (r.data->>'time_visited')::int >= COALESCE(p_value::int, 0);

    WHEN 'avg_time_spent_minutes' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'avg_time_spent_minutes' IS NOT NULL
          AND (r.data->>'avg_time_spent_minutes')::numeric >= COALESCE(p_value::numeric, 0);

    WHEN 'days_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'days_visited' IS NOT NULL
          AND (r.data->>'days_visited')::int >= COALESCE(p_value::int, 0);

    WHEN 'first_page_visited' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'first_page_visited' ILIKE '%' || COALESCE(p_value, '') || '%';

    WHEN 'first_visit' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'first_visit' IS NOT NULL
          AND (r.data->>'first_visit')::date >= COALESCE(p_value::date, '1970-01-01');

    WHEN 'most_recent_visit' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'most_recent_visit' IS NOT NULL
          AND (r.data->>'most_recent_visit')::date >= COALESCE(p_value::date, '1970-01-01');

    WHEN 'number_of_chats' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'number_of_chats' IS NOT NULL
          AND (r.data->>'number_of_chats')::int >= COALESCE(p_value::int, 0);

    WHEN 'visitor_score' THEN
      RETURN QUERY
        SELECT r.id FROM crm_records r
        WHERE r.module_id = p_module_id
          AND r.data->>'visitor_score' IS NOT NULL
          AND (r.data->>'visitor_score')::int >= COALESCE(p_value::int, 0);

    ELSE
      -- Unknown preset: return empty set
      RETURN;
  END CASE;
END;
$function$;

-- public.find_or_create_contact_by_email(p_org_id uuid, p_email text, p_name text)  [WRITES_ORG_ID, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.find_or_create_contact_by_email(p_org_id uuid, p_email text, p_name text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_contact_id uuid;
  v_contacts_module_id uuid;
BEGIN
  SELECT id INTO v_contacts_module_id
  FROM crm_modules
  WHERE organization_id = p_org_id AND key = 'Contacts';

  IF v_contacts_module_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT id INTO v_contact_id
  FROM crm_records
  WHERE organization_id = p_org_id
    AND module_id = v_contacts_module_id
    AND data->>'Email' = p_email
  LIMIT 1;

  IF v_contact_id IS NOT NULL THEN
    RETURN v_contact_id;
  END IF;

  INSERT INTO crm_records (organization_id, module_id, data, title)
  VALUES (
    p_org_id,
    v_contacts_module_id,
    jsonb_build_object('Email', p_email, 'First_Name', COALESCE(p_name, split_part(p_email, '@', 1))),
    COALESCE(p_name, p_email)
  )
  RETURNING id INTO v_contact_id;

  RETURN v_contact_id;
END;
$function$;

-- public.find_record_by_phone(phone_raw text, phone_normalized text)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.find_record_by_phone(phone_raw text, phone_normalized text)
 RETURNS TABLE(id uuid, org_id uuid, phone text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Try indexed phone column first (exact match)
  RETURN QUERY
    SELECT r.id, r.organization_id, r.phone
    FROM crm_records r
    WHERE r.phone = phone_normalized
       OR r.phone = phone_raw
    LIMIT 1;

  IF FOUND THEN RETURN; END IF;

  -- Fall back to JSONB data fields
  RETURN QUERY
    SELECT r.id, r.organization_id, r.phone
    FROM crm_records r
    WHERE r.data->>'phone' = phone_raw
       OR r.data->>'phone' = phone_normalized
       OR r.data->>'mobile' = phone_raw
       OR r.data->>'mobile' = phone_normalized
    LIMIT 1;
END;
$function$;

-- public.fix_wrong_org_batch(p_limit integer)  [OBSOLETE_CANDIDATE, refs=4, risk=low]
CREATE OR REPLACE FUNCTION public.fix_wrong_org_batch(p_limit integer DEFAULT 1000)
 RETURNS TABLE(records_moved integer, notes_moved integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_correct_org uuid := 'ac6e7228-2ea0-4582-8464-562c3e8ac56e'::uuid;
  v_wrong_org uuid := '00000000-0000-0000-0000-000000000001'::uuid;
  v_correct_module uuid := '7913796d-bda6-4fff-b81d-5f707b06b71b'::uuid;
  v_wrong_module uuid := '5c26eeee-ec93-406d-94eb-1e947ee75aaa'::uuid;
  v_rec_moved int;
  v_note_moved int;
  v_ids uuid[];
BEGIN
  SELECT array_agg(id) INTO v_ids
  FROM (
    SELECT id FROM crm_records
    WHERE organization_id = v_wrong_org AND module_id = v_wrong_module
    LIMIT p_limit
  ) sub;

  IF v_ids IS NULL OR array_length(v_ids, 1) IS NULL THEN
    RETURN QUERY SELECT 0, 0;
    RETURN;
  END IF;

  UPDATE crm_records
  SET organization_id = v_correct_org, module_id = v_correct_module
  WHERE id = ANY(v_ids);
  GET DIAGNOSTICS v_rec_moved = ROW_COUNT;

  UPDATE crm_notes
  SET organization_id = v_correct_org
  WHERE organization_id = v_wrong_org
    AND record_id = ANY(v_ids);
  GET DIAGNOSTICS v_note_moved = ROW_COUNT;

  RETURN QUERY SELECT v_rec_moved, v_note_moved;
END;
$function$;

-- public.fix_wrong_org_records()  [OBSOLETE_CANDIDATE, refs=4, risk=low]
CREATE OR REPLACE FUNCTION public.fix_wrong_org_records()
 RETURNS TABLE(records_moved integer, notes_moved integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_correct_org_id uuid := 'ac6e7228-2ea0-4582-8464-562c3e8ac56e'::uuid;
  v_wrong_org_id uuid := '00000000-0000-0000-0000-000000000001'::uuid;
  v_correct_contacts_module uuid := '7913796d-bda6-4fff-b81d-5f707b06b71b'::uuid;
  v_wrong_contacts_module uuid := '5c26eeee-ec93-406d-94eb-1e947ee75aaa'::uuid;
  v_records_moved int;
  v_notes_moved int;
BEGIN
  UPDATE crm_records
  SET organization_id = v_correct_org_id,
      module_id = v_correct_contacts_module
  WHERE organization_id = v_wrong_org_id
    AND module_id = v_wrong_contacts_module;
  GET DIAGNOSTICS v_records_moved = ROW_COUNT;

  UPDATE crm_notes
  SET organization_id = v_correct_org_id
  WHERE organization_id = v_wrong_org_id;
  GET DIAGNOSTICS v_notes_moved = ROW_COUNT;

  RETURN QUERY SELECT v_records_moved, v_notes_moved;
END;
$function$;

-- public.get_approval_detail(p_approval_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.get_approval_detail(p_approval_id uuid)
 RETURNS TABLE(id uuid, org_id uuid, process_id uuid, process_name text, process_description text, process_steps jsonb, record_id uuid, record_title text, record_data jsonb, module_id uuid, module_key text, module_name text, status text, current_step integer, context jsonb, action_payload jsonb, entity_snapshot jsonb, requested_by uuid, requested_by_name text, resolved_by uuid, resolved_by_name text, resolved_at timestamp with time zone, applied_at timestamp with time zone, expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Validate caller belongs to the approval's org
  IF NOT EXISTS (
    SELECT 1 FROM crm_approvals ca
    JOIN profiles p ON p.organization_id = ca.organization_id
    WHERE ca.id = p_approval_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      a.id,
      a.organization_id,
      a.process_id,
      p.name AS process_name,
      p.description AS process_description,
      p.steps AS process_steps,
      a.record_id,
      r.title AS record_title,
      r.data AS record_data,
      m.id AS module_id,
      m.key AS module_key,
      m.name AS module_name,
      a.status,
      a.current_step,
      a.context,
      a.action_payload,
      a.entity_snapshot,
      a.requested_by,
      pr.full_name AS requested_by_name,
      a.resolved_by,
      pres.full_name AS resolved_by_name,
      a.resolved_at,
      a.applied_at,
      a.expires_at,
      a.created_at,
      a.updated_at
    FROM crm_approvals a
    JOIN crm_approval_processes p ON a.process_id = p.id
    JOIN crm_records r ON a.record_id = r.id
    JOIN crm_modules m ON r.module_id = m.id
    LEFT JOIN profiles pr ON a.requested_by = pr.id
    LEFT JOIN profiles pres ON a.resolved_by = pres.id
    WHERE a.id = p_approval_id;
END;
$function$;

-- public.get_approval_inbox(p_org_id uuid, p_profile_id uuid, p_user_role text, p_status text, p_entity_type text, p_assigned_to_me boolean, p_requested_by_me boolean, p_limit integer, p_offset integer)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_approval_inbox(p_org_id uuid, p_profile_id uuid, p_user_role text, p_status text DEFAULT NULL::text, p_entity_type text DEFAULT NULL::text, p_assigned_to_me boolean DEFAULT false, p_requested_by_me boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, process_id uuid, process_name text, record_id uuid, record_title text, module_key text, module_name text, status text, current_step integer, total_steps integer, context jsonb, requested_by uuid, requested_by_name text, created_at timestamp with time zone, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Use table-qualified column to avoid ambiguity with output column "id"
  IF NOT EXISTS (
    SELECT 1 FROM profiles prf
    WHERE prf.user_id = auth.uid()
      AND prf.organization_id = p_org_id
      AND prf.id = p_profile_id
  ) THEN
    RETURN;
  END IF;

  RETURN QUERY
    SELECT
      a.id,
      a.process_id,
      ap.name AS process_name,
      a.record_id,
      r.title AS record_title,
      m.key AS module_key,
      m.name AS module_name,
      a.status,
      a.current_step,
      jsonb_array_length(ap.steps)::int AS total_steps,
      a.context,
      a.requested_by,
      pr.full_name AS requested_by_name,
      a.created_at,
      a.updated_at
    FROM crm_approvals a
    JOIN crm_approval_processes ap ON a.process_id = ap.id
    JOIN crm_records r ON a.record_id = r.id
    JOIN crm_modules m ON r.module_id = m.id
    LEFT JOIN profiles pr ON a.requested_by = pr.id
    WHERE a.organization_id = p_org_id
      AND (p_status IS NULL OR a.status = p_status)
      AND (p_entity_type IS NULL OR m.key = p_entity_type)
      AND (
        NOT p_assigned_to_me
        OR EXISTS (
          SELECT 1 FROM jsonb_array_elements(ap.steps) WITH ORDINALITY AS s(step, idx)
          WHERE (s.idx - 1) = a.current_step
            AND (
              s.step->>'approver_profile_id' = p_profile_id::text
              OR (s.step->>'approver_role' IS NOT NULL AND s.step->>'approver_role' = p_user_role)
            )
        )
      )
      AND (NOT p_requested_by_me OR a.requested_by = p_profile_id)
    ORDER BY a.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$function$;

-- public.get_approval_rules_for_module(p_module_id uuid, p_trigger_type text)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_approval_rules_for_module(p_module_id uuid, p_trigger_type text DEFAULT NULL::text)
 RETURNS SETOF crm_approval_rules
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_modules m
    JOIN profiles p ON p.organization_id = m.organization_id
    WHERE m.id = p_module_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT * FROM crm_approval_rules
    WHERE module_id = p_module_id
      AND is_enabled = true
      AND (p_trigger_type IS NULL OR trigger_type = p_trigger_type)
    ORDER BY priority ASC, created_at ASC;
END;
$function$;

-- public.get_change_feed_stats(p_org_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_change_feed_stats(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_stats jsonb;
BEGIN
  SELECT jsonb_build_object(
    'total_today', COUNT(*) FILTER (WHERE created_at >= CURRENT_DATE),
    'critical_count', COUNT(*) FILTER (WHERE severity = 'critical' AND reconciliation_status IN ('none', 'pending')),
    'high_count', COUNT(*) FILTER (WHERE severity = 'high' AND reconciliation_status IN ('none', 'pending')),
    'pending_review', COUNT(*) FILTER (WHERE requires_review = true AND reconciliation_status IN ('none', 'pending')),
    'sync_conflicts', COUNT(*) FILTER (WHERE sync_status = 'conflict')
  ) INTO v_stats
  FROM change_events
  WHERE organization_id = p_org_id
  AND created_at >= CURRENT_DATE - INTERVAL '7 days';

  RETURN COALESCE(v_stats, '{}'::jsonb);
END;
$function$;

-- public.get_command_console_stats(p_org_id uuid, p_user_id uuid)  [PARAM_NAMED_ORG_ID, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.get_command_console_stats(p_org_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today_start   timestamptz := date_trunc('day', now());
  v_today_end     timestamptz := v_today_start + interval '1 day';
  v_48h_ago       timestamptz := now() - interval '48 hours';
  v_seven_days    timestamptz := now() - interval '7 days';

  -- Enrollment stats
  v_started_today       int := 0;
  v_submitted_today     int := 0;
  v_activated_today     int := 0;
  v_pending_underwriting int := 0;
  v_docs_required       int := 0;
  v_activation_delayed  int := 0;
  v_rejected_count      int := 0;
  v_expiring_soon       int := 0;
  v_total_draft         int := 0;

  -- Billing stats
  v_collected_today     numeric(12,2) := 0;
  v_mrr                 numeric(12,2) := 0;
  v_failed_today        int := 0;
  v_pending_ach         int := 0;
  v_last_payment_at     timestamptz;

  -- Pipeline counts
  v_pipeline_leads      bigint := 0;
  v_pipeline_draft      int := 0;
  v_pipeline_in_progress int := 0;
  v_pipeline_submitted  int := 0;
  v_pipeline_approved   int := 0;
  v_pipeline_rejected   int := 0;
  v_pipeline_cancelled  int := 0;

  -- Operations stats
  v_overdue_tasks       int := 0;
  v_at_risk_deals       int := 0;

  -- Work queue
  v_work_queue          jsonb := '[]'::jsonb;
BEGIN
  -- ── Authorization: caller must belong to the target organization ──
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization';
  END IF;

  -- ── Authorization: p_user_id must match the authenticated user ──
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: p_user_id does not match authenticated user';
  END IF;

  -- =========================================================================
  -- ENROLLMENT STATS
  -- =========================================================================

  SELECT COUNT(*) INTO v_started_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND created_at >= v_today_start
    AND created_at < v_today_end;

  SELECT COUNT(*) INTO v_submitted_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'submitted'
    AND updated_at >= v_today_start
    AND updated_at < v_today_end;

  SELECT COUNT(*) INTO v_activated_today
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'approved'
    AND updated_at >= v_today_start
    AND updated_at < v_today_end;

  SELECT COUNT(*) INTO v_pending_underwriting
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'submitted';

  SELECT COUNT(DISTINCT es.enrollment_id) INTO v_docs_required
  FROM enrollment_steps es
  JOIN enrollments e ON e.id = es.enrollment_id
  WHERE es.organization_id = p_org_id
    AND es.is_completed = false
    AND e.status NOT IN ('approved', 'rejected', 'cancelled');

  SELECT COUNT(*) INTO v_activation_delayed
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'approved'
    AND effective_date IS NULL;

  SELECT COUNT(*) INTO v_rejected_count
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'rejected';

  SELECT COUNT(*) INTO v_expiring_soon
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status IN ('draft', 'in_progress')
    AND created_at < v_48h_ago;

  SELECT COUNT(*) INTO v_total_draft
  FROM enrollments
  WHERE organization_id = p_org_id
    AND status = 'draft';

  -- =========================================================================
  -- BILLING STATS
  -- =========================================================================

  SELECT COALESCE(SUM(amount), 0) INTO v_collected_today
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'success'
    AND processed_at >= v_today_start
    AND processed_at < v_today_end
    AND transaction_type = 'charge';

  SELECT COALESCE(SUM(amount), 0) INTO v_mrr
  FROM billing_schedules
  WHERE organization_id = p_org_id
    AND status = 'active';

  SELECT COUNT(*) INTO v_failed_today
  FROM billing_failures
  WHERE organization_id = p_org_id
    AND created_at >= v_today_start
    AND created_at < v_today_end
    AND resolved = false;

  SELECT COUNT(*) INTO v_pending_ach
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'pending';

  SELECT MAX(processed_at) INTO v_last_payment_at
  FROM billing_transactions
  WHERE organization_id = p_org_id
    AND status = 'success';

  -- =========================================================================
  -- PIPELINE COUNTS
  -- =========================================================================

  SELECT COUNT(*) INTO v_pipeline_leads
  FROM leads
  WHERE organization_id = p_org_id;

  SELECT
    COUNT(*) FILTER (WHERE status = 'draft') ,
    COUNT(*) FILTER (WHERE status = 'in_progress'),
    COUNT(*) FILTER (WHERE status = 'submitted'),
    COUNT(*) FILTER (WHERE status = 'approved'),
    COUNT(*) FILTER (WHERE status = 'rejected'),
    COUNT(*) FILTER (WHERE status = 'cancelled')
  INTO
    v_pipeline_draft,
    v_pipeline_in_progress,
    v_pipeline_submitted,
    v_pipeline_approved,
    v_pipeline_rejected,
    v_pipeline_cancelled
  FROM enrollments
  WHERE organization_id = p_org_id;

  -- =========================================================================
  -- OPERATIONS STATS (now scoped by org_id — fixes C-3)
  -- =========================================================================

  SELECT COUNT(*) INTO v_overdue_tasks
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND organization_id = p_org_id
    AND status != 'completed'
    AND due_at < now();

  SELECT COUNT(*) INTO v_at_risk_deals
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.key = 'deals'
    AND r.updated_at < v_seven_days
    AND r.data->>'stage' NOT IN ('Closed Won', 'Closed Lost', 'closed_won', 'closed_lost');

  -- =========================================================================
  -- WORK QUEUE (now scoped by org_id on tasks — fixes C-3)
  -- =========================================================================

  WITH queue_items AS (
    (
      SELECT
        bf.id::text AS id,
        'billing_failure' AS type,
        'Payment Failed — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        'ACH rejected · $' || bf.amount::text AS subtitle,
        1 AS priority,
        bf.created_at
      FROM billing_failures bf
      LEFT JOIN members m ON m.id = bf.member_id
      WHERE bf.organization_id = p_org_id
        AND bf.resolved = false
      ORDER BY bf.created_at DESC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        e.id::text AS id,
        'enrollment_review' AS type,
        'Review Application — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        'Submitted ' || to_char(e.updated_at, 'Mon DD') AS subtitle,
        2 AS priority,
        e.updated_at AS created_at
      FROM enrollments e
      LEFT JOIN members m ON m.id = e.primary_member_id
      WHERE e.organization_id = p_org_id
        AND e.status = 'submitted'
      ORDER BY e.updated_at ASC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        e.id::text AS id,
        'docs_pending' AS type,
        'Missing Docs — ' || COALESCE(m.first_name || ' ' || m.last_name, 'Unknown') AS title,
        es.step_key || ' incomplete' AS subtitle,
        3 AS priority,
        es.created_at
      FROM enrollment_steps es
      JOIN enrollments e ON e.id = es.enrollment_id
      LEFT JOIN members m ON m.id = e.primary_member_id
      WHERE es.organization_id = p_org_id
        AND es.is_completed = false
        AND e.status NOT IN ('approved', 'rejected', 'cancelled')
      ORDER BY es.created_at ASC
      LIMIT 3
    )

    UNION ALL

    (
      SELECT
        t.id::text AS id,
        'overdue_task' AS type,
        COALESCE(t.title, 'Untitled Task') AS title,
        'Due ' || to_char(t.due_at, 'Mon DD') AS subtitle,
        4 AS priority,
        t.due_at AS created_at
      FROM crm_tasks t
      WHERE t.assigned_to = p_user_id
        AND t.organization_id = p_org_id
        AND t.status != 'completed'
        AND t.due_at < now()
      ORDER BY t.due_at ASC
      LIMIT 3
    )
  )
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'id', qi.id,
      'type', qi.type,
      'title', qi.title,
      'subtitle', qi.subtitle,
      'priority', qi.priority,
      'createdAt', qi.created_at
    )
    ORDER BY qi.priority, qi.created_at ASC
  ), '[]'::jsonb)
  INTO v_work_queue
  FROM (SELECT * FROM queue_items ORDER BY priority, created_at ASC LIMIT 8) qi;

  -- =========================================================================
  -- RETURN COMBINED RESULT
  -- =========================================================================

  RETURN jsonb_build_object(
    'enrollmentStats', jsonb_build_object(
      'startedToday', v_started_today,
      'submittedToday', v_submitted_today,
      'activatedToday', v_activated_today,
      'pendingUnderwriting', v_pending_underwriting,
      'docsRequired', v_docs_required,
      'activationDelayed', v_activation_delayed,
      'rejectedCount', v_rejected_count,
      'expiringSoon', v_expiring_soon,
      'totalDraft', v_total_draft
    ),
    'billingStats', jsonb_build_object(
      'collectedToday', v_collected_today,
      'mrr', v_mrr,
      'failedToday', v_failed_today,
      'pendingAch', v_pending_ach,
      'lastSuccessfulPaymentAt', v_last_payment_at
    ),
    'pipelineCounts', jsonb_build_object(
      'leads', v_pipeline_leads,
      'draft', v_pipeline_draft,
      'inProgress', v_pipeline_in_progress,
      'submitted', v_pipeline_submitted,
      'approved', v_pipeline_approved,
      'rejected', v_pipeline_rejected,
      'cancelled', v_pipeline_cancelled
    ),
    'operationsStats', jsonb_build_object(
      'overdueTasks', v_overdue_tasks,
      'atRiskDeals', v_at_risk_deals
    ),
    'workQueue', v_work_queue
  );
END;
$function$;

-- public.get_crm_dashboard_stats(p_org_id uuid, p_module_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.get_crm_dashboard_stats(p_org_id uuid, p_module_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_mod_id uuid;
BEGIN
  -- Default to contacts module if not specified
  IF p_module_id IS NULL THEN
    SELECT id INTO v_mod_id FROM crm_modules
    WHERE organization_id = p_org_id AND key = 'contacts' LIMIT 1;
  ELSE
    v_mod_id := p_module_id;
  END IF;

  SELECT jsonb_build_object(
    -- Total counts
    'total_records', count(*),
    'total_individual', count(*) FILTER (WHERE record_type = 'individual'),
    'total_group', count(*) FILTER (WHERE record_type = 'group'),

    -- By plan type
    'healthshare', count(*) FILTER (WHERE market_type = 'healthshare'),
    'traditional_insurance', count(*) FILTER (WHERE market_type = 'traditional_insurance'),
    'unknown_plan_type', count(*) FILTER (WHERE market_type = 'unknown' OR market_type IS NULL),

    -- Tobacco
    'tobacco_users', count(*) FILTER (WHERE tobacco_user = true AND record_type = 'individual'),
    'non_tobacco', count(*) FILTER (WHERE tobacco_user = false AND record_type = 'individual'),
    'tobacco_unknown', count(*) FILTER (WHERE tobacco_user IS NULL AND record_type = 'individual'),

    -- Normalization / review
    'normalized', count(*) FILTER (WHERE normalization_status = 'normalized'),
    'needs_review', count(*) FILTER (WHERE normalization_status = 'needs_review'),
    'needs_classification', count(*) FILTER (WHERE market_type = 'unknown' OR market_type IS NULL),

    -- Carrier
    'with_carrier', count(*) FILTER (WHERE carrier_id IS NOT NULL),
    'missing_carrier', count(*) FILTER (WHERE carrier_id IS NULL AND record_type = 'individual'),

    -- Advisor assignment
    'with_advisor', count(*) FILTER (WHERE canonical_advisor_id IS NOT NULL OR normalized_advisor_name IS NOT NULL),
    'unassigned_advisor', count(*) FILTER (WHERE canonical_advisor_id IS NULL AND normalized_advisor_name IS NULL AND record_type = 'individual'),

    -- Import source
    'from_zoho', count(*) FILTER (WHERE import_source = 'zoho_csv'),
    'from_csv', count(*) FILTER (WHERE import_source = 'csv_import'),
    'manual_entry', count(*) FILTER (WHERE import_source = 'manual' OR import_source IS NULL),

    -- Time-based
    'created_last_7d', count(*) FILTER (WHERE created_at >= now() - interval '7 days'),
    'created_last_30d', count(*) FILTER (WHERE created_at >= now() - interval '30 days'),
    'updated_last_7d', count(*) FILTER (WHERE updated_at >= now() - interval '7 days')
  ) INTO v_result
  FROM crm_records
  WHERE organization_id = p_org_id
    AND (v_mod_id IS NULL OR module_id = v_mod_id);

  RETURN v_result;
END;
$function$;

-- public.get_dashboard_hero_stats(p_org_id uuid, p_user_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.get_dashboard_hero_stats(p_org_id uuid, p_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_today_start timestamptz := date_trunc('day', now());
  v_today_end   timestamptz := v_today_start + interval '1 day';
  v_seven_days  timestamptz := now() - interval '7 days';
  v_todays_task_count int;
  v_overdue_count int;
  v_at_risk_count int;
  v_new_this_week bigint;
BEGIN
  -- Validate caller belongs to org AND matches p_user_id
  IF NOT EXISTS (
    SELECT 1 FROM profiles
    WHERE user_id = auth.uid()
      AND organization_id = p_org_id
      AND id = p_user_id
  ) THEN
    RETURN jsonb_build_object(
      'todaysTaskCount', 0, 'overdueCount', 0,
      'atRiskCount', 0, 'newThisWeek', 0
    );
  END IF;

  SELECT COUNT(*) INTO v_todays_task_count
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND status != 'completed'
    AND due_at >= v_today_start
    AND due_at < v_today_end;

  SELECT COUNT(*) INTO v_overdue_count
  FROM crm_tasks
  WHERE assigned_to = p_user_id
    AND status != 'completed'
    AND due_at < now();

  SELECT COUNT(*) INTO v_at_risk_count
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.key = 'deals'
    AND r.updated_at < v_seven_days
    AND r.data->>'stage' NOT IN ('Closed Won', 'Closed Lost', 'closed_won', 'closed_lost');

  SELECT COUNT(*) INTO v_new_this_week
  FROM crm_records r
  JOIN crm_modules m ON m.id = r.module_id
  WHERE m.organization_id = p_org_id
    AND m.is_enabled = true
    AND r.created_at >= v_seven_days;

  RETURN jsonb_build_object(
    'todaysTaskCount', v_todays_task_count,
    'overdueCount', v_overdue_count,
    'atRiskCount', v_at_risk_count,
    'newThisWeek', v_new_this_week
  );
END;
$function$;

-- public.get_deal_stages(p_org_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_deal_stages(p_org_id uuid)
 RETURNS SETOF crm_deal_stages
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN; -- empty set, no information leakage
  END IF;

  RETURN QUERY
    SELECT * FROM crm_deal_stages
    WHERE organization_id = p_org_id AND is_active = true
    ORDER BY display_order;
END;
$function$;

-- public.get_linked_records(p_record_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_linked_records(p_record_id uuid)
 RETURNS TABLE(link_id uuid, link_type text, is_primary boolean, direction text, record_id uuid, record_title text, record_module_key text, record_module_name text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_records r
    JOIN profiles p ON p.organization_id = r.organization_id
    WHERE r.id = p_record_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      l.id AS link_id,
      l.link_type,
      l.is_primary,
      'outbound'::text AS direction,
      r2.id AS record_id,
      r2.title AS record_title,
      m.key AS record_module_key,
      m.name AS record_module_name,
      l.created_at
    FROM crm_record_links l
    JOIN crm_records r2 ON l.target_record_id = r2.id
    JOIN crm_modules m ON r2.module_id = m.id
    WHERE l.source_record_id = p_record_id

    UNION ALL

    SELECT
      l.id AS link_id,
      l.link_type,
      l.is_primary,
      'inbound'::text AS direction,
      r2.id AS record_id,
      r2.title AS record_title,
      m.key AS record_module_key,
      m.name AS record_module_name,
      l.created_at
    FROM crm_record_links l
    JOIN crm_records r2 ON l.source_record_id = r2.id
    JOIN crm_modules m ON r2.module_id = m.id
    WHERE l.target_record_id = p_record_id

    ORDER BY created_at DESC;
END;
$function$;

-- public.get_members_by_advisor(p_org_id uuid, p_limit integer)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_members_by_advisor(p_org_id uuid, p_limit integer DEFAULT 20)
 RETURNS TABLE(advisor_name text, record_count bigint, healthshare_count bigint, insurance_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    COALESCE(NULLIF(TRIM(r.normalized_advisor_name), ''), 'Unassigned') AS advisor_name,
    count(*) AS record_count,
    count(*) FILTER (WHERE r.market_type = 'healthshare') AS healthshare_count,
    count(*) FILTER (WHERE r.market_type = 'traditional_insurance') AS insurance_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY record_count DESC
  LIMIT p_limit;
$function$;

-- public.get_members_by_age_range(p_org_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_members_by_age_range(p_org_id uuid)
 RETURNS TABLE(age_bucket text, record_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    COALESCE(r.age_range, 'Unknown') AS age_bucket,
    count(*) AS record_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY
    CASE COALESCE(r.age_range, 'Unknown')
      WHEN '0-17' THEN 1
      WHEN '18-25' THEN 2
      WHEN '26-34' THEN 3
      WHEN '35-44' THEN 4
      WHEN '45-54' THEN 5
      WHEN '55-64' THEN 6
      WHEN '65+' THEN 7
      ELSE 8
    END;
$function$;

-- public.get_members_by_carrier(p_org_id uuid, p_limit integer)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_members_by_carrier(p_org_id uuid, p_limit integer DEFAULT 20)
 RETURNS TABLE(carrier_name text, carrier_type text, record_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    COALESCE(ic.carrier_name, 'No Carrier Assigned') AS carrier_name,
    COALESCE(ic.carrier_type, 'unknown') AS carrier_type,
    count(*) AS record_count
  FROM crm_records r
  LEFT JOIN insurance_carriers ic ON ic.id = r.carrier_id
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY ic.carrier_name, ic.carrier_type
  ORDER BY record_count DESC
  LIMIT p_limit;
$function$;

-- public.get_members_by_status(p_org_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_members_by_status(p_org_id uuid)
 RETURNS TABLE(member_status text, record_count bigint)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT
    COALESCE(NULLIF(TRIM(r.status), ''), 'No Status') AS member_status,
    count(*) AS record_count
  FROM crm_records r
  WHERE r.organization_id = p_org_id
    AND r.record_type = 'individual'
  GROUP BY 1
  ORDER BY record_count DESC;
$function$;

-- public.get_module_stats(p_org_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_module_stats(p_org_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_result jsonb;
  v_one_week_ago timestamptz := now() - interval '7 days';
BEGIN
  -- Validate caller belongs to org
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RETURN '[]'::jsonb;
  END IF;

  WITH module_counts AS (
    SELECT
      m.key AS module_key,
      COALESCE(m.name_plural, m.name || 's') AS module_name,
      COUNT(r.id) AS total_records,
      COUNT(r.id) FILTER (WHERE r.created_at >= v_one_week_ago) AS created_this_week
    FROM crm_modules m
    LEFT JOIN crm_records r ON r.module_id = m.id
    WHERE m.organization_id = p_org_id AND m.is_enabled = true
    GROUP BY m.key, m.name, m.name_plural
  ),
  legacy_leads AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE created_at >= v_one_week_ago) AS this_week
    FROM leads
    WHERE organization_id = p_org_id
  ),
  legacy_members AS (
    SELECT
      COUNT(*) AS total,
      COUNT(*) FILTER (WHERE created_at >= v_one_week_ago) AS this_week
    FROM members
    WHERE organization_id = p_org_id
  )
  SELECT jsonb_agg(
    jsonb_build_object(
      'moduleKey', mc.module_key,
      'moduleName', mc.module_name,
      'totalRecords', mc.total_records +
        CASE mc.module_key
          WHEN 'leads' THEN COALESCE((SELECT total FROM legacy_leads), 0)
          WHEN 'contacts' THEN COALESCE((SELECT total FROM legacy_members), 0)
          ELSE 0
        END,
      'createdThisWeek', mc.created_this_week +
        CASE mc.module_key
          WHEN 'leads' THEN COALESCE((SELECT this_week FROM legacy_leads), 0)
          WHEN 'contacts' THEN COALESCE((SELECT this_week FROM legacy_members), 0)
          ELSE 0
        END
    )
  ) INTO v_result
  FROM module_counts mc;

  RETURN COALESCE(v_result, '[]'::jsonb);
END;
$function$;

-- public.get_pending_scheduler_jobs(p_limit integer, p_job_types text[])  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_pending_scheduler_jobs(p_limit integer DEFAULT 100, p_job_types text[] DEFAULT NULL::text[])
 RETURNS TABLE(id uuid, org_id uuid, job_type text, entity_type text, entity_id uuid, record_id uuid, run_at timestamp with time zone, attempts integer, max_attempts integer, payload jsonb)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT 
    j.id,
    j.organization_id,
    j.job_type,
    j.entity_type,
    j.entity_id,
    j.record_id,
    j.run_at,
    j.attempts,
    j.max_attempts,
    j.payload
  FROM crm_scheduler_jobs j
  WHERE j.status = 'pending'
    AND j.run_at <= now()
    AND (p_job_types IS NULL OR j.job_type = ANY(p_job_types))
  ORDER BY j.run_at ASC
  LIMIT p_limit
  FOR UPDATE SKIP LOCKED;
END;
$function$;

-- public.get_record_stage_history(p_record_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.get_record_stage_history(p_record_id uuid)
 RETURNS TABLE(id uuid, from_stage text, to_stage text, duration_seconds integer, changed_by uuid, changed_by_name text, reason text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_records r
    JOIN profiles p ON p.organization_id = r.organization_id
    WHERE r.id = p_record_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- empty set
  END IF;

  RETURN QUERY
    SELECT
      h.id,
      h.from_stage,
      h.to_stage,
      h.duration_seconds,
      h.changed_by,
      p.full_name AS changed_by_name,
      h.reason,
      h.created_at
    FROM crm_deal_stage_history h
    LEFT JOIN profiles p ON h.changed_by = p.id
    WHERE h.record_id = p_record_id
    ORDER BY h.created_at DESC;
END;
$function$;

-- public.get_user_sender_addresses(p_profile_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.get_user_sender_addresses(p_profile_id uuid)
 RETURNS TABLE(id uuid, email text, name text, domain text, is_default boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_allowed_domain_ids uuid[];
BEGIN
  -- Use table alias to avoid ambiguity with output column "id"
  SELECT prf.organization_id INTO v_org_id FROM profiles prf WHERE prf.id = p_profile_id;
  SELECT ues.allowed_domain_ids INTO v_allowed_domain_ids FROM user_email_settings ues WHERE ues.profile_id = p_profile_id;

  IF v_allowed_domain_ids IS NULL OR array_length(v_allowed_domain_ids, 1) IS NULL THEN
    RETURN QUERY
    SELECT esa.id, esa.email, esa.name, ed.domain, esa.is_default
    FROM email_sender_addresses esa
    JOIN email_domains ed ON esa.domain_id = ed.id
    WHERE esa.organization_id = v_org_id
      AND ed.status = 'verified'
      AND esa.is_verified = true
    ORDER BY esa.is_default DESC, esa.email;
  ELSE
    RETURN QUERY
    SELECT esa.id, esa.email, esa.name, ed.domain, esa.is_default
    FROM email_sender_addresses esa
    JOIN email_domains ed ON esa.domain_id = ed.id
    WHERE esa.organization_id = v_org_id
      AND ed.id = ANY(v_allowed_domain_ids)
      AND ed.status = 'verified'
      AND esa.is_verified = true
    ORDER BY esa.is_default DESC, esa.email;
  END IF;
END;
$function$;

-- public.get_vendor_stats(p_org_id uuid)  [MECHANICAL, refs=4, risk=low]
CREATE OR REPLACE FUNCTION public.get_vendor_stats(p_org_id uuid)
 RETURNS TABLE(total_vendors bigint, active_vendors bigint, files_in_progress bigint, changes_last_7_days bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN QUERY
  SELECT
    (SELECT COUNT(*) FROM vendors WHERE organization_id = p_org_id)::bigint as total_vendors,
    (SELECT COUNT(*) FROM vendors WHERE organization_id = p_org_id AND status = 'active')::bigint as active_vendors,
    (SELECT COUNT(*) FROM vendor_files WHERE organization_id = p_org_id AND status IN ('pending', 'validating', 'processing'))::bigint as files_in_progress,
    (SELECT COUNT(*) FROM vendor_changes WHERE organization_id = p_org_id AND detected_at > now() - interval '7 days')::bigint as changes_last_7_days;
END;
$function$;

-- public.import_notes_batch(p_offset integer, p_limit integer)  [OBSOLETE_CANDIDATE, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.import_notes_batch(p_offset integer DEFAULT 0, p_limit integer DEFAULT 1000)
 RETURNS TABLE(imported integer, skipped integer, errors integer)
 LANGUAGE plpgsql
 SET statement_timeout TO '120s'
 SET search_path TO 'public'
AS $function$
DECLARE
  v_imported int := 0;
  v_skipped int := 0;
  v_errors int := 0;
  v_row RECORD;
  v_parent_record_id uuid;
  v_parent_org_id uuid;
  v_note_ts timestamptz;
  v_dup_exists boolean;
BEGIN
  FOR v_row IN
    SELECT * FROM import_notes_staging
    WHERE record_id IS NOT NULL AND record_id != 'Record Id' AND record_id != ''
      AND note_content IS NOT NULL AND note_content != ''
    ORDER BY row_num
    OFFSET p_offset LIMIT p_limit
  LOOP
    BEGIN
      SELECT id, organization_id INTO v_parent_record_id, v_parent_org_id
      FROM crm_records
      WHERE data->>'zoho_record_id' = v_row.parent_id
      LIMIT 1;

      -- Fallback: try source_record_id
      IF v_parent_record_id IS NULL THEN
        SELECT id, organization_id INTO v_parent_record_id, v_parent_org_id
        FROM crm_records
        WHERE source_record_id = v_row.parent_id
        LIMIT 1;
      END IF;

      IF v_parent_record_id IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      v_note_ts := COALESCE(_parse_import_datetime(v_row.created_time), now());

      -- Deduplicate: skip if same record + body + timestamp already exists
      SELECT EXISTS(
        SELECT 1 FROM crm_notes
        WHERE record_id = v_parent_record_id
          AND body = v_row.note_content
          AND created_at = v_note_ts
      ) INTO v_dup_exists;

      IF v_dup_exists THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      INSERT INTO crm_notes (organization_id, record_id, body, is_pinned, created_at, updated_at)
      VALUES (v_parent_org_id, v_parent_record_id, v_row.note_content, false,
              v_note_ts,
              COALESCE(_parse_import_datetime(v_row.modified_time), now()));
      v_imported := v_imported + 1;
    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN QUERY SELECT v_imported, v_skipped, v_errors;
END;
$function$;

-- public.import_notes_from_staging()  [OBSOLETE_CANDIDATE, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.import_notes_from_staging()
 RETURNS TABLE(imported integer, skipped integer, errors integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_imported int := 0;
  v_skipped int := 0;
  v_errors int := 0;
  v_row RECORD;
  v_parent_record_id uuid;
BEGIN
  SELECT id INTO v_org_id FROM organizations LIMIT 1;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found.';
  END IF;

  FOR v_row IN
    SELECT * FROM import_notes_staging
    WHERE record_id IS NOT NULL
      AND record_id != 'Record Id'
      AND note_content IS NOT NULL
      AND note_content != ''
    ORDER BY row_num
  LOOP
    BEGIN
      SELECT id INTO v_parent_record_id
      FROM crm_records
      WHERE organization_id = v_org_id
        AND data->>'zoho_record_id' = v_row.parent_id
      LIMIT 1;

      IF v_parent_record_id IS NULL THEN
        v_skipped := v_skipped + 1;
        CONTINUE;
      END IF;

      INSERT INTO crm_notes (
        organization_id, record_id, body, is_pinned, created_at, updated_at
      ) VALUES (
        v_org_id,
        v_parent_record_id,
        v_row.note_content,
        false,
        COALESCE(_parse_import_datetime(v_row.created_time), now()),
        COALESCE(_parse_import_datetime(v_row.modified_time), now())
      );

      v_imported := v_imported + 1;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RAISE NOTICE 'Notes import complete: % imported, % skipped (no parent), % errors', v_imported, v_skipped, v_errors;
  RETURN QUERY SELECT v_imported, v_skipped, v_errors;
END;
$function$;

-- public.increment_report_run_count(p_report_id uuid)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.increment_report_run_count(p_report_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM crm_reports rpt
    JOIN profiles p ON p.organization_id = rpt.organization_id
    WHERE rpt.id = p_report_id AND p.user_id = auth.uid()
  ) THEN
    RETURN; -- silently skip
  END IF;

  UPDATE public.crm_reports
  SET
    run_count = COALESCE(run_count, 0) + 1,
    last_run_at = now()
  WHERE id = p_report_id;
END;
$function$;

-- public.increment_user_email_count(p_profile_id uuid)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.increment_user_email_count(p_profile_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO user_email_settings (organization_id, profile_id, emails_sent_today, last_send_reset_at)
  SELECT organization_id, id, 1, CURRENT_DATE
  FROM profiles WHERE id = p_profile_id
  ON CONFLICT (profile_id)
  DO UPDATE SET
    emails_sent_today = CASE
      WHEN user_email_settings.last_send_reset_at < CURRENT_DATE THEN 1
      ELSE user_email_settings.emails_sent_today + 1
    END,
    last_send_reset_at = CURRENT_DATE;
END;
$function$;

-- public.is_email_unsubscribed(p_org_id uuid, p_email text)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.is_email_unsubscribed(p_org_id uuid, p_email text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM email_unsubscribes
    WHERE organization_id = p_org_id AND LOWER(email) = LOWER(p_email)
  );
END;
$function$;

-- public.log_conversation_assignment()  [WRITES_ORG_ID, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.log_conversation_assignment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF OLD.assigned_to IS DISTINCT FROM NEW.assigned_to THEN
    INSERT INTO inbox_assignments (
      organization_id, conversation_id, assigned_to, assigned_from, reason
    ) VALUES (
      NEW.organization_id, NEW.id, NEW.assigned_to, OLD.assigned_to, 'manual'
    );
  END IF;
  RETURN NEW;
END;
$function$;

-- public.log_crm_record_changes()  [WRITES_ORG_ID, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.log_crm_record_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid;
  v_action text;
  v_diff jsonb;
BEGIN
  -- Get actor ID using the new helper
  v_actor_id := current_profile_id();
  
  IF TG_OP = 'INSERT' THEN
    v_action := 'create';
    v_diff := jsonb_build_object('new', row_to_json(NEW)::jsonb);
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'update';
    v_diff := jsonb_build_object(
      'old', row_to_json(OLD)::jsonb,
      'new', row_to_json(NEW)::jsonb
    );
  ELSIF TG_OP = 'DELETE' THEN
    v_action := 'delete';
    v_diff := jsonb_build_object('old', row_to_json(OLD)::jsonb);
  END IF;
  
  INSERT INTO public.crm_audit_log (organization_id, actor_id, action, entity, entity_id, diff)
  VALUES (
    COALESCE(NEW.organization_id, OLD.organization_id),
    v_actor_id,
    v_action,
    'crm_records',
    COALESCE(NEW.id, OLD.id),
    v_diff
  );
  
  RETURN COALESCE(NEW, OLD);
END;
$function$;

-- public.log_deal_stage_change()  [WRITES_ORG_ID, refs=6, risk=low]
CREATE OR REPLACE FUNCTION public.log_deal_stage_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid;
  v_from_stage_id uuid;
  v_to_stage_id uuid;
  v_duration_seconds integer;
  v_last_change timestamptz;
  v_module_key text;
BEGIN
  -- Only trigger on stage changes
  IF OLD.stage IS DISTINCT FROM NEW.stage THEN
    -- Get the module key to check if this is a deals record
    SELECT key INTO v_module_key
    FROM crm_modules
    WHERE id = NEW.module_id;
    
    -- Only log for deals module
    IF v_module_key = 'deals' THEN
      -- Get actor ID
      SELECT id INTO v_actor_id FROM profiles WHERE user_id = auth.uid() LIMIT 1;
      
      -- Look up stage IDs
      SELECT id INTO v_from_stage_id 
      FROM crm_deal_stages 
      WHERE organization_id = NEW.organization_id AND key = OLD.stage;
      
      SELECT id INTO v_to_stage_id 
      FROM crm_deal_stages 
      WHERE organization_id = NEW.organization_id AND key = NEW.stage;
      
      -- Calculate duration in previous stage
      SELECT created_at INTO v_last_change
      FROM crm_deal_stage_history
      WHERE record_id = NEW.id
      ORDER BY created_at DESC
      LIMIT 1;
      
      IF v_last_change IS NOT NULL THEN
        v_duration_seconds := EXTRACT(EPOCH FROM (now() - v_last_change))::integer;
      ELSIF OLD.stage IS NOT NULL THEN
        -- If no history, use record created_at
        v_duration_seconds := EXTRACT(EPOCH FROM (now() - NEW.created_at))::integer;
      END IF;
      
      -- Insert history record
      INSERT INTO crm_deal_stage_history (
        organization_id, record_id, from_stage, to_stage, 
        from_stage_id, to_stage_id, duration_seconds, changed_by
      ) VALUES (
        NEW.organization_id, NEW.id, OLD.stage, NEW.stage,
        v_from_stage_id, v_to_stage_id, v_duration_seconds, v_actor_id
      );
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$;

-- public.log_validation_run(p_org_id uuid, p_rule_id uuid, p_record_id uuid, p_trigger text, p_result text, p_field_value jsonb, p_errors jsonb, p_context jsonb)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.log_validation_run(p_org_id uuid, p_rule_id uuid, p_record_id uuid, p_trigger text, p_result text, p_field_value jsonb DEFAULT NULL::jsonb, p_errors jsonb DEFAULT '[]'::jsonb, p_context jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_run_id uuid;
BEGIN
  INSERT INTO crm_validation_rule_runs (
    organization_id, rule_id, record_id, trigger, result, field_value, errors, context
  ) VALUES (
    p_org_id, p_rule_id, p_record_id, p_trigger, p_result, p_field_value, p_errors, p_context
  )
  RETURNING id INTO v_run_id;
  
  RETURN v_run_id;
END;
$function$;

