-- public.merge_crm_records(p_keeper_id uuid, p_duplicate_id uuid, p_user_id uuid, p_merged_data jsonb, p_merged_status text, p_merged_email text, p_merged_phone text, p_merged_owner uuid)  [WRITES_ORG_ID, refs=5, risk=low]
CREATE OR REPLACE FUNCTION public.merge_crm_records(p_keeper_id uuid, p_duplicate_id uuid, p_user_id uuid, p_merged_data jsonb DEFAULT NULL::jsonb, p_merged_status text DEFAULT NULL::text, p_merged_email text DEFAULT NULL::text, p_merged_phone text DEFAULT NULL::text, p_merged_owner uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_keeper       crm_records%ROWTYPE;
  v_duplicate    crm_records%ROWTYPE;
  v_user_org     uuid;
  v_final_data   jsonb;
  v_final_status text;
  v_final_email  text;
  v_final_phone  text;
  v_final_owner  uuid;
  v_final_title  text;
  v_moved_notes  int := 0;
  v_moved_tasks  int := 0;
  v_moved_attach int := 0;
  v_moved_links  int := 0;
BEGIN
  IF p_keeper_id = p_duplicate_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Keeper and duplicate must be different records');
  END IF;

  SELECT * INTO v_keeper    FROM crm_records WHERE id = p_keeper_id    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Keeper record not found');
  END IF;

  SELECT * INTO v_duplicate FROM crm_records WHERE id = p_duplicate_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Duplicate record not found');
  END IF;

  SELECT organization_id INTO v_user_org FROM profiles WHERE id = p_user_id;
  IF v_user_org IS NULL OR v_user_org <> v_keeper.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized for this organization');
  END IF;

  IF v_keeper.organization_id    <> v_duplicate.organization_id    THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records belong to different organizations');
  END IF;
  IF v_keeper.module_id <> v_duplicate.module_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Records belong to different modules');
  END IF;

  v_final_data := COALESCE(
    p_merged_data,
    (
      SELECT COALESCE(jsonb_object_agg(k, v), '{}'::jsonb)
      FROM (
        SELECT
          k,
          CASE
            WHEN (v_keeper.data -> k) IS NULL
                 OR v_keeper.data ->> k IS NULL
                 OR v_keeper.data ->> k = ''
              THEN v_duplicate.data -> k
            ELSE v_keeper.data -> k
          END AS v
        FROM (
          SELECT DISTINCT k FROM (
            SELECT jsonb_object_keys(COALESCE(v_keeper.data,    '{}'::jsonb)) AS k
            UNION
            SELECT jsonb_object_keys(COALESCE(v_duplicate.data, '{}'::jsonb)) AS k
          ) keys
        ) all_keys
      ) merged
      WHERE v IS NOT NULL
    )
  );

  v_final_email  := COALESCE(NULLIF(p_merged_email, ''), NULLIF(v_keeper.email, ''), NULLIF(v_duplicate.email, ''));
  v_final_phone  := COALESCE(NULLIF(p_merged_phone, ''), NULLIF(v_keeper.phone, ''), NULLIF(v_duplicate.phone, ''));
  v_final_owner  := COALESCE(p_merged_owner, v_keeper.owner_id, v_duplicate.owner_id);
  v_final_title  := COALESCE(NULLIF(v_keeper.title, ''), NULLIF(v_duplicate.title, ''));

  v_final_status := COALESCE(
    NULLIF(p_merged_status, ''),
    CASE
      WHEN v_keeper.status    = 'Active' THEN v_keeper.status
      WHEN v_duplicate.status = 'Active' THEN v_duplicate.status
      ELSE COALESCE(NULLIF(v_keeper.status, ''), NULLIF(v_duplicate.status, ''))
    END
  );

  UPDATE crm_notes SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_notes = ROW_COUNT;

  -- legacy notes table (record_id is uuid in this DB; previously cast to text by mistake)
  BEGIN
    EXECUTE 'UPDATE public.notes SET record_id = $1 WHERE record_id = $2'
      USING p_keeper_id, p_duplicate_id;
  EXCEPTION WHEN undefined_table OR undefined_column THEN
    NULL;
  END;

  UPDATE crm_tasks       SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_tasks = ROW_COUNT;

  UPDATE crm_attachments SET record_id = p_keeper_id WHERE record_id = p_duplicate_id;
  GET DIAGNOSTICS v_moved_attach = ROW_COUNT;

  DELETE FROM crm_record_links
   WHERE source_record_id = p_duplicate_id
     AND EXISTS (
       SELECT 1 FROM crm_record_links kl
        WHERE kl.source_record_id = p_keeper_id
          AND kl.target_record_id = crm_record_links.target_record_id
          AND kl.link_type        = crm_record_links.link_type
     );
  UPDATE crm_record_links SET source_record_id = p_keeper_id WHERE source_record_id = p_duplicate_id;

  DELETE FROM crm_record_links
   WHERE target_record_id = p_duplicate_id
     AND EXISTS (
       SELECT 1 FROM crm_record_links kl
        WHERE kl.target_record_id = p_keeper_id
          AND kl.source_record_id = crm_record_links.source_record_id
          AND kl.link_type        = crm_record_links.link_type
     );
  UPDATE crm_record_links SET target_record_id = p_keeper_id WHERE target_record_id = p_duplicate_id;
  DELETE FROM crm_record_links WHERE source_record_id = target_record_id;

  GET DIAGNOSTICS v_moved_links = ROW_COUNT;

  DO $blk$
  DECLARE
    r record;
    sql text;
  BEGIN
    FOR r IN
      SELECT
        tc.table_schema,
        tc.table_name,
        kcu.column_name
      FROM information_schema.table_constraints tc
      JOIN information_schema.key_column_usage kcu
        ON tc.constraint_name = kcu.constraint_name
       AND tc.table_schema    = kcu.table_schema
      JOIN information_schema.constraint_column_usage ccu
        ON ccu.constraint_name = tc.constraint_name
       AND ccu.table_schema    = tc.table_schema
      WHERE tc.constraint_type = 'FOREIGN KEY'
        AND ccu.table_schema   = 'public'
        AND ccu.table_name     = 'crm_records'
        AND ccu.column_name    = 'id'
        AND NOT (tc.table_name IN ('crm_notes','crm_tasks','crm_attachments','crm_record_links'))
    LOOP
      BEGIN
        sql := format('UPDATE %I.%I SET %I = $1 WHERE %I = $2',
          r.table_schema, r.table_name, r.column_name, r.column_name);
        EXECUTE sql USING p_keeper_id, p_duplicate_id;
      EXCEPTION WHEN unique_violation THEN
        sql := format('DELETE FROM %I.%I WHERE %I = $1',
          r.table_schema, r.table_name, r.column_name);
        EXECUTE sql USING p_duplicate_id;
      WHEN others THEN
        RAISE WARNING 'merge_crm_records: skipped %.%.%: %',
          r.table_schema, r.table_name, r.column_name, SQLERRM;
      END;
    END LOOP;
  END;
  $blk$;

  UPDATE crm_records
  SET data       = v_final_data,
      email      = v_final_email,
      phone      = v_final_phone,
      status     = v_final_status,
      owner_id   = v_final_owner,
      title      = v_final_title,
      updated_at = now()
  WHERE id = p_keeper_id;

  DELETE FROM crm_records WHERE id = p_duplicate_id;

  BEGIN
    INSERT INTO crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
    VALUES (
      v_keeper.organization_id, p_user_id, 'record', p_keeper_id, 'merge',
      jsonb_build_object(
        'kept_id',           p_keeper_id,
        'deleted_id',        p_duplicate_id,
        'deleted_snapshot',  to_jsonb(v_duplicate),
        'moved_notes',       v_moved_notes,
        'moved_tasks',       v_moved_tasks,
        'moved_attachments', v_moved_attach,
        'moved_links',       v_moved_links,
        'merged_at',         now()
      )
    );
  EXCEPTION WHEN others THEN
    RAISE WARNING 'merge_crm_records: audit insert failed: %', SQLERRM;
  END;

  RETURN jsonb_build_object('success', true,
    'kept_id', p_keeper_id, 'deleted_id', p_duplicate_id,
    'moved_notes', v_moved_notes, 'moved_tasks', v_moved_tasks,
    'moved_attachments', v_moved_attach, 'moved_links', v_moved_links);

EXCEPTION WHEN others THEN
  RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$function$;

-- public.needs_apply_sla()  [MECHANICAL, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.needs_apply_sla()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  days_to_target integer;
BEGIN
  -- ========================================
  -- Track status change time
  -- ========================================
  IF TG_OP = 'INSERT' THEN
    -- Set initial status change timestamp
    IF NEW.last_status_change_at IS NULL THEN
      NEW.last_status_change_at := now();
    END IF;

    -- Set default target dates if not provided
    -- SLA durations can be configured per organization in org_settings.sla_config
    -- Defaults: 3 days for initial review, 45 days for completion
    IF NEW.target_initial_review_date IS NULL THEN
      NEW.target_initial_review_date := (current_date + COALESCE(
        (SELECT (settings->'sla_config'->>'initial_review_days')::int
         FROM public.organizations
         WHERE id = NEW.organization_id),
        3  -- Production default: 3 business days
      ));
    END IF;

    IF NEW.target_completion_date IS NULL THEN
      NEW.target_completion_date := (current_date + COALESCE(
        (SELECT (settings->'sla_config'->>'completion_days')::int
         FROM public.organizations
         WHERE id = NEW.organization_id),
        45  -- Production default: 45 days (industry standard)
      ));
    END IF;

    -- Also set sla_target_date if not set (for backwards compatibility)
    IF NEW.sla_target_date IS NULL THEN
      NEW.sla_target_date := NEW.target_completion_date;
    END IF;

  ELSIF TG_OP = 'UPDATE' THEN
    -- Track when status changes
    IF NEW.status IS DISTINCT FROM OLD.status THEN
      NEW.last_status_change_at := now();
    END IF;
  END IF;

  -- ========================================
  -- Compute urgency_light
  -- ========================================

  -- Terminal/completed statuses are always green (no outstanding SLA)
  IF NEW.status IN ('paid', 'closed', 'denied', 'cancelled') THEN
    NEW.urgency_light := 'green';
    RETURN NEW;
  END IF;

  -- If no target date, default to green unless explicitly set
  IF NEW.target_completion_date IS NULL THEN
    IF NEW.urgency_light IS NULL THEN
      NEW.urgency_light := 'green';
    END IF;
    RETURN NEW;
  END IF;

  -- Compute days to target completion (today-based simple SLA)
  days_to_target := NEW.target_completion_date - current_date;

  -- Apply urgency thresholds
  -- Thresholds can be configured per organization in org_settings.sla_config
  -- Defaults: green (5+ days), orange (0-4 days), red (overdue)
  -- Note: Customize urgency_green_days in organization settings to adjust threshold
  IF days_to_target >= COALESCE(
    (SELECT (settings->'sla_config'->>'urgency_green_days')::int
     FROM public.organizations
     WHERE id = NEW.organization_id),
    5  -- Production default: 5+ days = green
  ) THEN
    NEW.urgency_light := 'green';   -- Comfortably on track
  ELSIF days_to_target >= 0 THEN
    NEW.urgency_light := 'orange';  -- Approaching deadline
  ELSE
    NEW.urgency_light := 'red';     -- Past target date (overdue)
  END IF;

  RETURN NEW;
END;
$function$;

-- public.queue_integration_job(p_org_id uuid, p_job_type text, p_payload jsonb, p_run_at timestamp with time zone, p_source_event_id uuid, p_source_rule_id uuid, p_idempotency_key text)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.queue_integration_job(p_org_id uuid, p_job_type text, p_payload jsonb, p_run_at timestamp with time zone DEFAULT now(), p_source_event_id uuid DEFAULT NULL::uuid, p_source_rule_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
  v_job_id uuid;
BEGIN
  IF p_idempotency_key IS NOT NULL THEN
    SELECT id INTO v_job_id
    FROM integration_jobs
    WHERE idempotency_key = p_idempotency_key
      AND status NOT IN ('failed', 'cancelled');

    IF v_job_id IS NOT NULL THEN
      RETURN v_job_id;
    END IF;
  END IF;

  INSERT INTO integration_jobs (
    organization_id, job_type, payload, run_at, source_event_id, source_rule_id, idempotency_key
  ) VALUES (
    p_org_id, p_job_type, p_payload, p_run_at, p_source_event_id, p_source_rule_id, p_idempotency_key
  )
  RETURNING id INTO v_job_id;

  RETURN v_job_id;
END;
$function$;

-- public.recalc_crm_commission_summary(p_member_id uuid, p_org_id uuid)  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.recalc_crm_commission_summary(p_member_id uuid, p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_record_id           uuid;
  v_count               int;
  v_total_amount        numeric(12,2);
  v_pending_amount      numeric(12,2);
  v_paid_amount         numeric(12,2);
  v_last_transaction_at timestamptz;
BEGIN
  IF p_member_id IS NULL OR p_org_id IS NULL THEN
    RETURN;
  END IF;

  -- Find the linked CRM contact record (created/maintained by sync_member_to_crm).
  SELECT cr.id
    INTO v_record_id
    FROM public.crm_records cr
    JOIN public.crm_modules m ON m.id = cr.module_id
   WHERE m.organization_id = p_org_id
     AND m.key   = 'contacts'
     AND cr.organization_id = p_org_id
     AND cr.data->>'linked_member_id' = p_member_id::text
   ORDER BY cr.updated_at DESC NULLS LAST
   LIMIT 1;

  IF v_record_id IS NULL THEN
    RETURN;  -- No CRM record to update yet; sync_member_to_crm will eventually create one.
  END IF;

  -- Aggregate every commission transaction for this member.
  SELECT
    COUNT(*),
    COALESCE(SUM(commission_amount), 0),
    COALESCE(SUM(commission_amount) FILTER (WHERE status IN ('pending', 'approved', 'held')), 0),
    COALESCE(SUM(commission_amount) FILTER (WHERE status = 'paid'), 0),
    MAX(updated_at)
    INTO v_count, v_total_amount, v_pending_amount, v_paid_amount, v_last_transaction_at
    FROM public.commission_transactions
   WHERE member_id = p_member_id
     AND organization_id = p_org_id;

  UPDATE public.crm_records
     SET data = COALESCE(data, '{}'::jsonb) || jsonb_build_object(
       'commission_summary', jsonb_build_object(
         'count',                v_count,
         'total_amount',         v_total_amount,
         'pending_amount',       v_pending_amount,
         'paid_amount',          v_paid_amount,
         'last_transaction_at',  v_last_transaction_at
       )
     ),
     updated_at = now()
   WHERE id = v_record_id;
END;
$function$;

-- public.record_change_event(p_org_id uuid, p_source_type text, p_source_name text, p_change_type text, p_entity_type text, p_entity_id uuid, p_entity_title text, p_title text, p_description text, p_diff jsonb, p_payload jsonb, p_actor_id uuid, p_actor_type text, p_severity text, p_requires_review boolean)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.record_change_event(p_org_id uuid, p_source_type text, p_source_name text, p_change_type text, p_entity_type text, p_entity_id uuid, p_entity_title text, p_title text, p_description text DEFAULT NULL::text, p_diff jsonb DEFAULT NULL::jsonb, p_payload jsonb DEFAULT '{}'::jsonb, p_actor_id uuid DEFAULT NULL::uuid, p_actor_type text DEFAULT 'user'::text, p_severity text DEFAULT NULL::text, p_requires_review boolean DEFAULT NULL::boolean)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_severity text;
  v_requires_review boolean;
  v_change_id uuid;
  v_actor_name text;
BEGIN
  IF p_severity IS NULL THEN
    v_severity := CASE
      WHEN p_change_type IN ('termination', 'integration_error') THEN 'critical'
      WHEN p_change_type IN ('plan_change', 'sync_conflict') OR p_change_type LIKE 'status_change:inactive%' THEN 'high'
      WHEN p_change_type IN ('enrollment', 'member_new') THEN 'medium'
      WHEN p_change_type = 'create' THEN 'low'
      ELSE 'info'
    END;
  ELSE
    v_severity := p_severity;
  END IF;

  IF p_requires_review IS NULL THEN
    v_requires_review := v_severity IN ('critical', 'high') OR p_change_type IN ('termination', 'plan_change');
  ELSE
    v_requires_review := p_requires_review;
  END IF;

  IF p_actor_id IS NOT NULL THEN
    SELECT full_name INTO v_actor_name FROM profiles WHERE id = p_actor_id;
  END IF;

  INSERT INTO change_events (
    organization_id, source_type, source_name, change_type, entity_type, entity_id,
    entity_title, title, description, diff, payload, actor_id, actor_name,
    actor_type, severity, requires_review, reconciliation_status
  ) VALUES (
    p_org_id, p_source_type, p_source_name, p_change_type, p_entity_type, p_entity_id,
    p_entity_title, p_title, p_description, p_diff, p_payload, p_actor_id, v_actor_name,
    p_actor_type, v_severity, v_requires_review,
    CASE WHEN v_requires_review THEN 'pending' ELSE 'none' END
  )
  RETURNING id INTO v_change_id;

  RETURN v_change_id;
END;
$function$;

-- public.record_tracking_event(p_tracking_id uuid, p_event_type text, p_ip_address text, p_user_agent text, p_clicked_url text)  [WRITES_ORG_ID, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.record_tracking_event(p_tracking_id uuid, p_event_type text, p_ip_address text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_clicked_url text DEFAULT NULL::text)
 RETURNS json
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_recipient email_campaign_recipients%ROWTYPE;
  v_campaign email_campaigns%ROWTYPE;
BEGIN
  -- Find recipient by tracking ID
  SELECT * INTO v_recipient
  FROM email_campaign_recipients
  WHERE tracking_id = p_tracking_id;

  IF v_recipient.id IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Tracking ID not found');
  END IF;

  -- Get campaign
  SELECT * INTO v_campaign
  FROM email_campaigns
  WHERE id = v_recipient.campaign_id;

  -- Record the event
  INSERT INTO campaign_tracking_events (
    organization_id, campaign_id, recipient_id, tracking_id,
    event_type, ip_address, user_agent, clicked_url
  ) VALUES (
    v_campaign.organization_id, v_recipient.campaign_id, v_recipient.id, p_tracking_id,
    p_event_type, p_ip_address, p_user_agent, p_clicked_url
  );

  -- Update recipient stats
  IF p_event_type = 'open' THEN
    UPDATE email_campaign_recipients
    SET
      opened_at = COALESCE(opened_at, now()),
      last_opened_at = now(),
      open_count = open_count + 1,
      status = CASE WHEN status NOT IN ('clicked', 'unsubscribed') THEN 'opened' ELSE status END
    WHERE id = v_recipient.id;

    -- Update campaign stats (only increment unique opens)
    IF v_recipient.opened_at IS NULL THEN
      UPDATE email_campaigns
      SET opened_count = opened_count + 1
      WHERE id = v_recipient.campaign_id;
    END IF;

  ELSIF p_event_type = 'click' THEN
    UPDATE email_campaign_recipients
    SET
      clicked_at = COALESCE(clicked_at, now()),
      last_clicked_at = now(),
      click_count = click_count + 1,
      opened_at = COALESCE(opened_at, now()), -- click implies open
      status = CASE WHEN status != 'unsubscribed' THEN 'clicked' ELSE status END
    WHERE id = v_recipient.id;

    -- Update campaign stats (only increment unique clicks)
    IF v_recipient.clicked_at IS NULL THEN
      UPDATE email_campaigns
      SET
        clicked_count = clicked_count + 1,
        opened_count = CASE WHEN v_recipient.opened_at IS NULL
                       THEN opened_count + 1 ELSE opened_count END
      WHERE id = v_recipient.campaign_id;
    END IF;

  ELSIF p_event_type = 'unsubscribe' THEN
    UPDATE email_campaign_recipients
    SET
      unsubscribed_at = now(),
      status = 'unsubscribed'
    WHERE id = v_recipient.id;

    UPDATE email_campaigns
    SET unsubscribed_count = unsubscribed_count + 1
    WHERE id = v_recipient.campaign_id;
  END IF;

  RETURN json_build_object('success', true);
END;
$function$;

-- public.recover_zoho_notes_for_org(p_org_id uuid, p_since timestamp with time zone)  [OBSOLETE_CANDIDATE, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.recover_zoho_notes_for_org(p_org_id uuid, p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(inserted_count integer, total_considered integer, duplicate_count integer, orphan_parent_count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inserted int := 0;
  v_dupes    int := 0;
  v_total    int := 0;
  v_orphans  int := 0;
BEGIN
  IF p_org_id IS NULL THEN
    RAISE EXCEPTION 'p_org_id is required';
  END IF;

  -- ------------------------------------------------------------------------
  -- Working set: every staged row that has a body and resolves to a current
  -- crm_records.id in the requested org.
  -- ------------------------------------------------------------------------
  CREATE TEMP TABLE _zoho_notes_work ON COMMIT DROP AS
  SELECT
    s.row_num,
    r.id                                                        AS crm_record_id,
    p_org_id                                                    AS org_id,
    trim(s.note_content)                                        AS body,
    COALESCE(
      NULLIF(s.created_time, '')::timestamp AT TIME ZONE 'America/Denver',
      now()
    )                                                           AS created_at
  FROM import_notes_staging s
  JOIN crm_records r
    ON r.organization_id = p_org_id
   AND (
         r.data->>'zoho_record_id' = s.parent_id
      OR r.data->>'zoho_record_id' = 'zcrm_' || s.parent_id
      OR replace(r.data->>'zoho_record_id', 'zcrm_', '') = s.parent_id
     )
  WHERE s.note_content IS NOT NULL
    AND trim(s.note_content) <> ''
    AND (p_since IS NULL OR NULLIF(s.created_time, '')::timestamp >= p_since);

  SELECT count(*) INTO v_total FROM _zoho_notes_work;

  -- ------------------------------------------------------------------------
  -- Drop rows whose body already exists on the same record near the same time.
  -- ------------------------------------------------------------------------
  DELETE FROM _zoho_notes_work t
  USING crm_notes n
  WHERE n.record_id = t.crm_record_id
    AND n.body = t.body
    AND n.created_at BETWEEN t.created_at - interval '1 minute'
                          AND t.created_at + interval '1 minute';

  GET DIAGNOSTICS v_dupes = ROW_COUNT;

  -- ------------------------------------------------------------------------
  -- Insert.
  -- ------------------------------------------------------------------------
  INSERT INTO crm_notes (organization_id, record_id, body, is_pinned, created_by, created_at, updated_at)
  SELECT
    t.org_id,
    t.crm_record_id,
    t.body,
    false,
    NULL::uuid,
    t.created_at,
    now()
  FROM _zoho_notes_work t;

  GET DIAGNOSTICS v_inserted = ROW_COUNT;

  -- ------------------------------------------------------------------------
  -- Count staging rows whose parent record we couldn't match.
  -- ------------------------------------------------------------------------
  SELECT count(*)
    INTO v_orphans
  FROM import_notes_staging s
  LEFT JOIN crm_records r
    ON r.organization_id = p_org_id
   AND (
         r.data->>'zoho_record_id' = s.parent_id
      OR r.data->>'zoho_record_id' = 'zcrm_' || s.parent_id
      OR replace(r.data->>'zoho_record_id', 'zcrm_', '') = s.parent_id
     )
  WHERE r.id IS NULL
    AND s.note_content IS NOT NULL
    AND trim(s.note_content) <> ''
    AND (p_since IS NULL OR NULLIF(s.created_time, '')::timestamp >= p_since);

  RETURN QUERY SELECT v_inserted, v_total, v_dupes, v_orphans;
END
$function$;

-- public.rpc_advisor_retention_widget(p_org_id uuid, p_months integer)  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.rpc_advisor_retention_widget(p_org_id uuid, p_months integer DEFAULT 6)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE v_result jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(
    jsonb_build_object(
      'month', TO_CHAR(month_date, 'YYYY-MM'),
      'retention_rate', ROUND(
        CASE WHEN total_count > 0
          THEN (active_count::numeric / total_count) * 100
          ELSE 0
        END, 1),
      'active_count', active_count,
      'total_count', total_count
    ) ORDER BY month_date
  ), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT
      gs.month_date,
      COUNT(m.id) AS total_count,
      COUNT(m.id) FILTER (WHERE
        m.status = 'active'
        OR (m.termination_date IS NOT NULL AND m.termination_date > gs.month_date + interval '1 month')
      ) AS active_count
    FROM generate_series(
      date_trunc('month', CURRENT_DATE - (p_months || ' months')::interval)::date,
      date_trunc('month', CURRENT_DATE)::date,
      '1 month'::interval
    ) AS gs(month_date)
    LEFT JOIN members m ON m.organization_id = p_org_id
      AND m.effective_date <= gs.month_date + interval '1 month'
      AND (m.termination_date IS NULL OR m.termination_date >= gs.month_date)
    LEFT JOIN advisors a ON a.id = m.advisor_id AND a.organization_id = p_org_id
    WHERE a.id IS NOT NULL  -- Only count members with advisors
    GROUP BY gs.month_date
  ) monthly;

  RETURN jsonb_build_object('months', v_result);
END;
$function$;

-- public.seed_default_deal_stages(p_org_id uuid)  [WRITES_ORG_ID, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.seed_default_deal_stages(p_org_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM profiles WHERE user_id = auth.uid() AND organization_id = p_org_id
  ) THEN
    RAISE EXCEPTION 'Unauthorized: caller does not belong to this organization';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM crm_deal_stages WHERE organization_id = p_org_id) THEN
    INSERT INTO crm_deal_stages (organization_id, key, name, color, probability, is_won, is_lost, display_order)
    VALUES
      (p_org_id, 'qualification', 'Qualification', '#8b5cf6', 10, false, false, 1),
      (p_org_id, 'needs_analysis', 'Needs Analysis', '#6366f1', 25, false, false, 2),
      (p_org_id, 'proposal', 'Proposal', '#3b82f6', 50, false, false, 3),
      (p_org_id, 'negotiation', 'Negotiation', '#0ea5e9', 75, false, false, 4),
      (p_org_id, 'closed_won', 'Closed Won', '#22c55e', 100, true, false, 5),
      (p_org_id, 'closed_lost', 'Closed Lost', '#ef4444', 0, false, true, 6);
  END IF;
END;
$function$;

-- public.sync_advisor_to_crm_records()  [MECHANICAL, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.sync_advisor_to_crm_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module_id uuid;
  v_owner_id uuid;
  v_org_id uuid;
  v_data jsonb;
BEGIN
  -- Determine the org_id (advisors table uses organization_id)
  IF TG_OP = 'DELETE' THEN
    v_org_id := OLD.organization_id;
  ELSE
    v_org_id := NEW.organization_id;
  END IF;

  -- Find the "advisors" CRM module for this org
  SELECT id INTO v_module_id
    FROM crm_modules
    WHERE organization_id = v_org_id AND key = 'advisors';

  IF v_module_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  -- Get owner (profile_id of the advisor)
  IF TG_OP != 'DELETE' THEN
    v_owner_id := NEW.profile_id;
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_data := jsonb_build_object(
      'advisor_code', NEW.advisor_code,
      'first_name', NEW.first_name,
      'last_name', NEW.last_name,
      'agency_name', NEW.agency_name,
      'license_number', NEW.license_number,
      'npn', NEW.npn,
      'commission_tier', NEW.commission_tier,
      'enrollment_code', NEW.enrollment_code,
      'contract_date', NEW.contract_date,
      'primary_channel', NEW.primary_channel,
      'agent_role', NEW.agent_role
    );

    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, system,
      created_at, updated_at
    ) VALUES (
      v_org_id,
      v_module_id,
      v_owner_id,
      NEW.first_name || ' ' || NEW.last_name,
      NEW.status,
      NEW.email,
      NEW.phone,
      v_data,
      jsonb_build_object(
        'source_table', 'advisors',
        'source_id', NEW.id::text,
        'advisor_code', NEW.advisor_code,
        'synced', true
      ),
      NEW.created_at,
      now()
    );

  ELSIF TG_OP = 'UPDATE' THEN
    v_data := jsonb_build_object(
      'advisor_code', NEW.advisor_code,
      'first_name', NEW.first_name,
      'last_name', NEW.last_name,
      'agency_name', NEW.agency_name,
      'license_number', NEW.license_number,
      'npn', NEW.npn,
      'commission_tier', NEW.commission_tier,
      'enrollment_code', NEW.enrollment_code,
      'contract_date', NEW.contract_date,
      'primary_channel', NEW.primary_channel,
      'agent_role', NEW.agent_role
    );

    UPDATE crm_records SET
      title = NEW.first_name || ' ' || NEW.last_name,
      status = NEW.status,
      email = NEW.email,
      phone = NEW.phone,
      data = v_data,
      owner_id = v_owner_id,
      updated_at = now()
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'advisors'
      AND system->>'source_id' = NEW.id::text;

  ELSIF TG_OP = 'DELETE' THEN
    DELETE FROM crm_records
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'advisors'
      AND system->>'source_id' = OLD.id::text;

    RETURN OLD;
  END IF;

  RETURN NEW;
END;
$function$;

-- public.sync_enrollment_to_crm_records()  [MECHANICAL, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.sync_enrollment_to_crm_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_module_id uuid;
  v_market_type text;
  v_carrier_id uuid;
  v_plan_name text;
  v_data_patch jsonb;
BEGIN
  IF TG_OP = 'UPDATE'
    AND OLD.status = NEW.status
    AND OLD.selected_plan_id IS NOT DISTINCT FROM NEW.selected_plan_id
  THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('submitted', 'approved', 'active') THEN
    RETURN NEW;
  END IF;

  IF NEW.primary_member_id IS NULL THEN
    RETURN NEW;
  END IF;

  SELECT id INTO v_module_id
    FROM crm_modules WHERE organization_id = NEW.organization_id AND key = 'members';

  IF v_module_id IS NULL THEN RETURN NEW; END IF;

  IF NEW.selected_plan_id IS NOT NULL THEN
    SELECT name INTO v_plan_name FROM plans WHERE id = NEW.selected_plan_id;
  END IF;

  v_market_type := CASE
    WHEN NEW.plan_type ILIKE '%health%share%' OR NEW.plan_type ILIKE '%sharing%' THEN 'healthshare'
    WHEN NEW.plan_type ILIKE '%insurance%' OR NEW.plan_type ILIKE '%traditional%' THEN 'traditional_insurance'
    WHEN v_plan_name ILIKE '%MPB%' OR v_plan_name ILIKE '%MPowering%'
      OR v_plan_name ILIKE '%Sedera%' OR v_plan_name ILIKE '%Zion%'
      OR v_plan_name ILIKE '%sharing%' THEN 'healthshare'
    ELSE NULL
  END;

  IF NEW.snapshot IS NOT NULL AND NEW.snapshot->>'carrier' IS NOT NULL THEN
    SELECT id INTO v_carrier_id
      FROM insurance_carriers
      WHERE organization_id = NEW.organization_id
        AND LOWER(TRIM(carrier_name)) = LOWER(TRIM(NEW.snapshot->>'carrier'))
        AND is_active = true
      LIMIT 1;
  END IF;

  -- Build in chunks to stay under 100-arg limit
  v_data_patch := jsonb_build_object(
    'enrollment_id', NEW.id,
    'enrollment_number', NEW.enrollment_number,
    'enrollment_status', NEW.status,
    'selected_plan_id', NEW.selected_plan_id,
    'plan_name', v_plan_name,
    'plan_type', NEW.plan_type,
    'effective_date', NEW.effective_date,
    'requested_effective_date', NEW.requested_effective_date,
    'base_monthly_cost', NEW.base_monthly_cost,
    'tobacco_surcharge', NEW.tobacco_surcharge,
    'total_monthly_cost', NEW.total_monthly_cost,
    'enrollment_date', NEW.enrollment_date,
    'enrollment_source', COALESCE(NEW.source, NEW.enrollment_source),
    'first_billing_date', NEW.first_billing_date,
    'next_billing_date', NEW.next_billing_date,
    'next_billing_amount', NEW.next_billing_amount,
    'permanent_bill_day', NEW.permanent_bill_day,
    'pay_type', NEW.pay_type,
    'is_paid', NEW.is_paid,
    'last_payment_date', NEW.last_payment_date
  );

  v_data_patch := v_data_patch || jsonb_build_object(
    'product_paid_through_date', NEW.product_paid_through_date,
    'administration_fee', NEW.administration_fee,
    'association_fee', NEW.association_fee,
    'iua_fee', NEW.iua_fee,
    'product_fee', NEW.product_fee,
    'monthly_contribution_fee', NEW.monthly_contribution_fee,
    'hold_date', NEW.hold_date,
    'hold_reason', NEW.hold_reason,
    'hold_return_date', NEW.hold_return_date,
    'hold_amount', NEW.hold_amount,
    'contract_number', NEW.contract_number,
    'contract_length', NEW.contract_length,
    'underwriter', NEW.underwriter,
    'refund_requested', NEW.refund_requested,
    'refund_provided', NEW.refund_provided,
    'tpv_code', NEW.tpv_code,
    'product_label', NEW.product_label,
    'product_benefit', NEW.product_benefit,
    'period_label', NEW.period_label,
    'product_status', NEW.product_status
  );

  v_data_patch := v_data_patch || jsonb_build_object(
    'product_stage', NEW.product_stage,
    'product_source', NEW.product_source,
    'product_source_detail', NEW.product_source_detail,
    'product_code', NEW.product_code,
    'sale_date', NEW.sale_date,
    'renewal_date', NEW.renewal_date,
    'category', NEW.category,
    'category3', NEW.category3,
    'category4', NEW.category4,
    'enroller_id', NEW.enroller_id,
    'enroller_name', NEW.enroller_name,
    'product_agent_id', NEW.product_agent_id,
    'product_agent_label', NEW.product_agent_label,
    'agent_code', NEW.agent_code,
    'assigned_agents', NEW.assigned_agents
  );

  UPDATE crm_records SET
    market_type = COALESCE(v_market_type, market_type),
    tobacco_user = COALESCE(NEW.primary_is_smoker, tobacco_user),
    carrier_id = COALESCE(v_carrier_id, carrier_id),
    data = data || v_data_patch,
    normalization_status = CASE
      WHEN COALESCE(v_market_type, market_type) IS NOT NULL
        AND COALESCE(v_market_type, market_type) != 'unknown'
      THEN 'normalized'
      ELSE normalization_status
    END,
    updated_at = now()
  WHERE module_id = v_module_id
    AND system->>'source_table' = 'members'
    AND system->>'source_id' = NEW.primary_member_id::text;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'sync_enrollment_to_crm_records failed for enrollment %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$function$;

-- public.sync_member_to_crm()  [WRITES_ORG_ID, refs=5, risk=low]
CREATE OR REPLACE FUNCTION public.sync_member_to_crm()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_contacts_module_id uuid;
  v_existing_record_id uuid;
  v_record_title       text;
BEGIN
  SELECT id INTO v_contacts_module_id
  FROM crm_modules
  WHERE organization_id = NEW.organization_id
    AND key = 'contacts'
    AND is_enabled = true
  LIMIT 1;

  IF v_contacts_module_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_record_title := TRIM(COALESCE(NEW.first_name, '') || ' ' || COALESCE(NEW.last_name, ''));
  IF v_record_title = '' THEN
    v_record_title := COALESCE(NEW.email, 'Member ' || NEW.id::text);
  END IF;

  -- 1. Exact linked_member_id match (cheapest and most specific).
  SELECT id INTO v_existing_record_id
  FROM crm_records
  WHERE module_id = v_contacts_module_id
    AND organization_id    = NEW.organization_id
    AND (data->>'linked_member_id') = NEW.id::text
  LIMIT 1;

  -- 2. Email match (case-insensitive) when no link yet.
  IF v_existing_record_id IS NULL
     AND NEW.email IS NOT NULL
     AND NEW.email <> '' THEN
    SELECT id INTO v_existing_record_id
    FROM crm_records
    WHERE module_id = v_contacts_module_id
      AND organization_id    = NEW.organization_id
      AND email IS NOT NULL
      AND LOWER(email) = LOWER(NEW.email)
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  -- 3. Phone + name match. Phone alone is too loose (household lines,
  --    office numbers), so we require the name to line up too.
  IF v_existing_record_id IS NULL
     AND NEW.phone IS NOT NULL
     AND NEW.phone <> ''
     AND NEW.first_name IS NOT NULL
     AND NEW.last_name  IS NOT NULL THEN
    SELECT id INTO v_existing_record_id
    FROM crm_records
    WHERE module_id = v_contacts_module_id
      AND organization_id    = NEW.organization_id
      AND phone     = NEW.phone
      AND LOWER(COALESCE(data->>'first_name','')) = LOWER(NEW.first_name)
      AND LOWER(COALESCE(data->>'last_name', '')) = LOWER(NEW.last_name)
    ORDER BY updated_at DESC NULLS LAST
    LIMIT 1;
  END IF;

  IF v_existing_record_id IS NOT NULL THEN
    -- Update + stamp linked_member_id so subsequent syncs short-circuit on
    -- the fast path.
    UPDATE crm_records
    SET
      title = COALESCE(NULLIF(title, ''), v_record_title),
      email = COALESCE(NULLIF(email, ''), NEW.email),
      phone = COALESCE(NULLIF(phone, ''), NEW.phone),
      -- Don't stomp an Active status with a Pending one — but do promote
      -- the other way around.
      status = CASE
        WHEN NEW.status = 'Active' THEN 'Active'
        WHEN status = 'Active'     THEN status
        ELSE COALESCE(NEW.status, status)
      END,
      data = jsonb_set(
        jsonb_set(
          jsonb_set(
            jsonb_set(
              COALESCE(data, '{}'::jsonb),
              '{first_name}', to_jsonb(COALESCE(NEW.first_name, data->>'first_name'))
            ),
            '{last_name}',  to_jsonb(COALESCE(NEW.last_name,  data->>'last_name'))
          ),
          '{email}',        to_jsonb(COALESCE(NEW.email,      data->>'email'))
        ),
        '{linked_member_id}', to_jsonb(NEW.id::text)
      ),
      updated_at = now()
    WHERE id = v_existing_record_id;

    RETURN NEW;
  END IF;

  -- Nothing matched — insert a fresh Contact.
  INSERT INTO crm_records (
    organization_id, module_id, title, email, phone, status, data, search,
    created_at, updated_at
  ) VALUES (
    NEW.organization_id,
    v_contacts_module_id,
    v_record_title,
    NEW.email,
    NEW.phone,
    COALESCE(NEW.status, 'Active'),
    jsonb_build_object(
      'first_name',       NEW.first_name,
      'last_name',        NEW.last_name,
      'email',            NEW.email,
      'phone',            NEW.phone,
      'contact_status',   COALESCE(NEW.status, 'Active'),
      'linked_member_id', NEW.id::text,
      'source',           'enrollment_sync'
    ),
    to_tsvector('english', COALESCE(v_record_title, '') || ' ' || COALESCE(NEW.email, '')),
    now(), now()
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'sync_member_to_crm failed for member %: %', NEW.id, SQLERRM;
  RETURN NEW;
END;
$function$;

-- public.sync_member_to_crm_records()  [WRITES_ORG_ID, refs=3, risk=low]
CREATE OR REPLACE FUNCTION public.sync_member_to_crm_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_module_id uuid;
  v_owner_id uuid;
  v_advisor_code text;
  v_advisor_name text;
  v_org_id uuid;
  v_data jsonb;
  v_market_type text;
  v_canonical_advisor_id uuid;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_org_id := OLD.organization_id;
  ELSE
    v_org_id := NEW.organization_id;
  END IF;

  SELECT id INTO v_module_id
    FROM crm_modules WHERE organization_id = v_org_id AND key = 'members';

  IF v_module_id IS NULL THEN
    IF TG_OP = 'DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    DELETE FROM crm_records
      WHERE module_id = v_module_id
        AND system->>'source_table' = 'members'
        AND system->>'source_id' = OLD.id::text;
    RETURN OLD;
  END IF;

  v_canonical_advisor_id := NEW.advisor_id;
  IF NEW.advisor_id IS NOT NULL THEN
    SELECT a.advisor_code, a.first_name || ' ' || a.last_name, p.id
    INTO v_advisor_code, v_advisor_name, v_owner_id
    FROM advisors a LEFT JOIN profiles p ON p.id = a.profile_id
    WHERE a.id = NEW.advisor_id;
  END IF;

  v_market_type := CASE
    WHEN NEW.plan_type ILIKE '%health%share%' OR NEW.plan_type ILIKE '%sharing%' THEN 'healthshare'
    WHEN NEW.plan_type ILIKE '%insurance%' OR NEW.plan_type ILIKE '%traditional%' THEN 'traditional_insurance'
    WHEN NEW.plan_name ILIKE '%MPB%' OR NEW.plan_name ILIKE '%MPowering%'
      OR NEW.plan_name ILIKE '%Sedera%' OR NEW.plan_name ILIKE '%Zion%'
      OR NEW.plan_name ILIKE '%sharing%' THEN 'healthshare'
    ELSE 'unknown'
  END;

  -- Build data in chunks to stay under 100-arg limit
  v_data := jsonb_build_object(
    'member_number', NEW.member_number,
    'first_name', NEW.first_name,
    'last_name', NEW.last_name,
    'date_of_birth', NEW.date_of_birth,
    'gender', NEW.gender,
    'marital_status', NEW.marital_status,
    'address_line1', NEW.address_line1,
    'address_line2', NEW.address_line2,
    'city', NEW.city,
    'state', NEW.state,
    'zip_code', NEW.postal_code,
    'advisor_id', NEW.advisor_id,
    'advisor_code', v_advisor_code,
    'advisor_name', v_advisor_name,
    'plan_name', NEW.plan_name,
    'plan_type', NEW.plan_type,
    'effective_date', NEW.effective_date,
    'monthly_share', NEW.monthly_share,
    'coverage_type', NEW.coverage_type,
    'program_type', NEW.program_type
  );

  v_data := v_data || jsonb_build_object(
    'enrollment_source', COALESCE(NEW.custom_fields->>'enrollment_source', ''),
    'county', NEW.county,
    'phone2', NEW.phone2,
    'phone3', NEW.phone3,
    'fax', NEW.fax,
    'email2', NEW.email2,
    'email3', NEW.email3,
    'do_not_call', NEW.do_not_call,
    'company_name', NEW.company_name,
    'position', NEW.position,
    'department', NEW.department,
    'division', NEW.division,
    'ethnicity', NEW.ethnicity,
    'height', NEW.height,
    'weight', NEW.weight,
    'disability', NEW.disability,
    'source', NEW.source,
    'referral', NEW.referral,
    'member_type', NEW.member_type,
    'stage', NEW.stage,
    'internal_id', NEW.internal_id,
    'external_username', NEW.external_username
  );

  IF TG_OP = 'INSERT' THEN
    INSERT INTO crm_records (
      organization_id, module_id, owner_id,
      title, status, email, phone,
      data, system,
      market_type, canonical_advisor_id, normalized_advisor_name,
      tobacco_user, record_type, import_source, normalization_status,
      created_at, updated_at
    ) VALUES (
      NEW.organization_id, v_module_id, v_owner_id,
      NEW.first_name || ' ' || NEW.last_name,
      NEW.status, NEW.email, NEW.phone,
      v_data,
      jsonb_build_object(
        'source_table', 'members',
        'source_id', NEW.id::text,
        'member_number', NEW.member_number,
        'synced', true
      ),
      v_market_type, v_canonical_advisor_id, v_advisor_name,
      COALESCE(NEW.is_smoker, false),
      'individual', 'enrollment',
      CASE WHEN v_market_type != 'unknown' THEN 'normalized' ELSE 'needs_review' END,
      NEW.created_at, now()
    );
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE crm_records SET
      title = NEW.first_name || ' ' || NEW.last_name,
      status = NEW.status, email = NEW.email, phone = NEW.phone,
      owner_id = COALESCE(v_owner_id, owner_id),
      data = v_data,
      system = jsonb_build_object(
        'source_table', 'members', 'source_id', NEW.id::text,
        'member_number', NEW.member_number, 'synced', true
      ),
      market_type = COALESCE(v_market_type, market_type),
      canonical_advisor_id = COALESCE(v_canonical_advisor_id, canonical_advisor_id),
      normalized_advisor_name = COALESCE(v_advisor_name, normalized_advisor_name),
      tobacco_user = COALESCE(NEW.is_smoker, tobacco_user),
      record_type = COALESCE(record_type, 'individual'),
      import_source = COALESCE(import_source, 'enrollment'),
      updated_at = now()
    WHERE module_id = v_module_id
      AND system->>'source_table' = 'members'
      AND system->>'source_id' = OLD.id::text;

    IF NOT FOUND THEN
      INSERT INTO crm_records (
        organization_id, module_id, owner_id,
        title, status, email, phone,
        data, system,
        market_type, canonical_advisor_id, normalized_advisor_name,
        tobacco_user, record_type, import_source, normalization_status,
        created_at, updated_at
      ) VALUES (
        NEW.organization_id, v_module_id, v_owner_id,
        NEW.first_name || ' ' || NEW.last_name,
        NEW.status, NEW.email, NEW.phone,
        v_data,
        jsonb_build_object(
          'source_table', 'members', 'source_id', NEW.id::text,
          'member_number', NEW.member_number, 'synced', true
        ),
        v_market_type, v_canonical_advisor_id, v_advisor_name,
        COALESCE(NEW.is_smoker, false),
        'individual', 'enrollment',
        CASE WHEN v_market_type != 'unknown' THEN 'normalized' ELSE 'needs_review' END,
        COALESCE(NEW.created_at, now()), now()
      );
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'sync_member_to_crm_records failed for member %: %', NEW.id, SQLERRM;
    RETURN NEW;
END;
$function$;

-- public.undismiss_duplicate_pair(p_a_id uuid, p_b_id uuid)  [WRITES_ORG_ID, refs=2, risk=low]
CREATE OR REPLACE FUNCTION public.undismiss_duplicate_pair(p_a_id uuid, p_b_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_profile_id uuid;
  v_actor_org_id     uuid;
  v_actor_role       text;
  v_left_id          uuid;
  v_right_id         uuid;
  v_deleted          int;
BEGIN
  IF p_a_id IS NULL OR p_b_id IS NULL OR p_a_id = p_b_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Two different record ids are required');
  END IF;

  SELECT id, organization_id, crm_role
    INTO v_actor_profile_id, v_actor_org_id, v_actor_role
    FROM public.profiles
   WHERE user_id = auth.uid()
   LIMIT 1;

  IF v_actor_profile_id IS NULL OR v_actor_role NOT IN ('crm_admin', 'crm_manager') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Only CRM admins and managers can undismiss duplicate pairs');
  END IF;

  v_left_id  := LEAST(p_a_id, p_b_id);
  v_right_id := GREATEST(p_a_id, p_b_id);

  DELETE FROM public.crm_duplicate_dismissals
   WHERE organization_id  = v_actor_org_id
     AND left_record_id  = v_left_id
     AND right_record_id = v_right_id;
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  IF v_deleted > 0 THEN
    INSERT INTO public.crm_audit_log (organization_id, actor_id, entity, entity_id, action, diff)
    VALUES (
      v_actor_org_id,
      v_actor_profile_id,
      'record',
      v_left_id,
      'duplicate_undismissed',
      jsonb_build_object('left_id', v_left_id, 'right_id', v_right_id)
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'left_id', v_left_id, 'right_id', v_right_id, 'removed', v_deleted);
END;
$function$;

-- public.upsert_contacts_batch(p_offset integer, p_limit integer)  [OBSOLETE_CANDIDATE, refs=6, risk=low]
CREATE OR REPLACE FUNCTION public.upsert_contacts_batch(p_offset integer DEFAULT 0, p_limit integer DEFAULT 500)
 RETURNS TABLE(inserted integer, updated integer, skipped integer, errors integer)
 LANGUAGE plpgsql
 SET statement_timeout TO '120s'
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_org_id uuid;
  v_module_id uuid;
  v_inserted int := 0;
  v_updated int := 0;
  v_skipped int := 0;
  v_errors int := 0;
  v_row RECORD;
  v_existing_id uuid;
  v_data jsonb;
  v_match_method text;
  v_market text;
  v_advisor_name text;
  v_agent_name text;
  v_canonical_advisor_id uuid;
  v_norm_status text;
BEGIN
  -- Fixed: resolve org from the module that actually exists
  SELECT m.organization_id, m.id INTO v_org_id, v_module_id
  FROM crm_modules m WHERE m.key = 'contacts' LIMIT 1;

  IF v_org_id IS NULL OR v_module_id IS NULL THEN
    RAISE EXCEPTION 'Contacts module not found.';
  END IF;

  FOR v_row IN
    SELECT * FROM import_contacts_staging
    WHERE record_id IS NOT NULL
      AND record_id != 'Record Id'
      AND record_id != ''
      AND (first_name IS NOT NULL OR last_name IS NOT NULL)
    ORDER BY row_num
    OFFSET p_offset
    LIMIT p_limit
  LOOP
    BEGIN
      v_existing_id := NULL;
      v_match_method := NULL;

      IF NULLIF(TRIM(v_row.email), '') IS NOT NULL THEN
        SELECT id INTO v_existing_id FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND LOWER(email) = LOWER(TRIM(v_row.email))
        ORDER BY updated_at DESC LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_method := 'email'; END IF;
      END IF;

      IF v_existing_id IS NULL AND NULLIF(v_row.record_id, '') IS NOT NULL THEN
        SELECT id INTO v_existing_id FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND data->>'zoho_record_id' = v_row.record_id
        LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_method := 'zoho_record_id'; END IF;
      END IF;

      IF v_existing_id IS NULL AND NULLIF(v_row.record_id, '') IS NOT NULL THEN
        SELECT id INTO v_existing_id FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND source_record_id = v_row.record_id
        LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_method := 'source_record_id'; END IF;
      END IF;

      IF v_existing_id IS NULL
         AND NULLIF(v_row.first_name, '') IS NOT NULL
         AND NULLIF(v_row.last_name, '') IS NOT NULL
         AND NULLIF(v_row.phone, '') IS NOT NULL
      THEN
        SELECT id INTO v_existing_id FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND LOWER(data->>'first_name') = LOWER(v_row.first_name)
          AND LOWER(data->>'last_name') = LOWER(v_row.last_name)
          AND phone = v_row.phone
        ORDER BY updated_at DESC LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_method := 'name_phone'; END IF;
      END IF;

      v_data := jsonb_build_object(
        'zoho_record_id', NULLIF(v_row.record_id, ''),
        'zoho_contact_owner_id', NULLIF(v_row.contact_owner_id, ''),
        'zoho_producer_id', NULLIF(v_row.producer_name_id, ''),
        'first_name', NULLIF(v_row.first_name, ''),
        'last_name', NULLIF(v_row.last_name, ''),
        'contact_name', NULLIF(v_row.contact_name, ''),
        'salutation', NULLIF(v_row.salutation, ''),
        'middle_initial', NULLIF(v_row.middle_initial, ''),
        'title', NULLIF(v_row.title, ''),
        'date_of_birth', _parse_import_date(v_row.date_of_birth),
        'birth_month', NULLIF(v_row.birth_month, ''),
        'primary_member_gender', NULLIF(v_row.primary_member_gender, ''),
        'marital_status', NULLIF(v_row.marital_status, ''),
        'secondary_email', NULLIF(v_row.secondary_email, ''),
        'mobile', NULLIF(v_row.mobile, ''),
        'work_phone', NULLIF(v_row.work_phone, ''),
        'fax', NULLIF(v_row.fax, ''),
        'email', NULLIF(TRIM(v_row.email), ''),
        'phone', NULLIF(v_row.phone, ''),
        'mailing_street', NULLIF(v_row.mailing_street, ''),
        'mailing_city', NULLIF(v_row.mailing_city, ''),
        'mailing_zip', NULLIF(v_row.mailing_zip, ''),
        'mailing_state', NULLIF(v_row.mailing_state, ''),
        'contact_status', NULLIF(v_row.contact_status, ''),
        'contact_owner', NULLIF(v_row.contact_owner, ''),
        'lead_source', NULLIF(v_row.lead_source, ''),
        'affiliate', NULLIF(v_row.affiliate, ''),
        'producer_name', NULLIF(v_row.producer_name, ''),
        'referral_source', NULLIF(v_row.referral_source, ''),
        'referring_member', NULLIF(v_row.referring_member, ''),
        'tag', NULLIF(v_row.tag, ''),
        'territories', NULLIF(v_row.territories, ''),
        'company_association', NULLIF(v_row.company_association, ''),
        'data_source', NULLIF(v_row.data_source, '')
      );

      v_data := v_data || jsonb_build_object(
        'spouse', NULLIF(v_row.spouse, ''),
        'spouse_dob', _parse_import_date(v_row.spouse_dob),
        'spouse_ss_number', NULLIF(v_row.spouse_ss_number, ''),
        'spouse_address', NULLIF(v_row.spouse_address, ''),
        'spouse_phone_number', NULLIF(v_row.spouse_phone_number, ''),
        'spouse_email', NULLIF(v_row.spouse_email, ''),
        'child_1', NULLIF(v_row.child_1, ''),
        'child_1_dob', _parse_import_date(v_row.child_1_dob),
        'child_1_ss_number', NULLIF(v_row.child_1_ss_number, ''),
        'child_1_address', NULLIF(v_row.child_1_address, ''),
        'child_1_phone_number', NULLIF(v_row.child_1_phone_number, ''),
        'child_1_email', NULLIF(v_row.child_1_email, ''),
        'child_2', NULLIF(v_row.child_2, ''),
        'child_2_dob', _parse_import_date(v_row.child_2_dob),
        'child_2_ss_number', NULLIF(v_row.child_2_ss_number, ''),
        'child_2_address', NULLIF(v_row.child_2_address, ''),
        'child_2_phone_number', NULLIF(v_row.child_2_phone_number, ''),
        'child_2_email', NULLIF(v_row.child_2_email, ''),
        'child_3', NULLIF(v_row.child_3, ''),
        'child_3_dob', _parse_import_date(v_row.child_3_dob),
        'child_3_ss_number', NULLIF(v_row.child_3_ss_number, ''),
        'child_3_address', NULLIF(v_row.child_3_address, ''),
        'child_3_phone_number', NULLIF(v_row.child_3_phone_number, ''),
        'child_3_email', NULLIF(v_row.child_3_email, ''),
        'child_4', NULLIF(v_row.child_4, ''),
        'child_4_dob', _parse_import_date(v_row.child_4_dob),
        'child_4_ss_number', NULLIF(v_row.child_4_ss_number, ''),
        'child_4_address', NULLIF(v_row.child_4_address, ''),
        'child_4_phone_number', NULLIF(v_row.child_4_phone_number, ''),
        'child_4_email', NULLIF(v_row.child_4_email, ''),
        'child_5', NULLIF(v_row.child_5, ''),
        'child_5_dob', _parse_import_date(v_row.child_5_dob),
        'child_5_ss_number', NULLIF(v_row.child_5_ss_number, ''),
        'child_5_address', NULLIF(v_row.child_5_address, ''),
        'child_5_phone_number', NULLIF(v_row.child_5_phone_number, ''),
        'child_5_email', NULLIF(v_row.child_5_email, '')
      );

      v_data := v_data || jsonb_build_object(
        'product', NULLIF(v_row.product, ''),
        'coverage_option', NULLIF(v_row.coverage_option, ''),
        'carrier', NULLIF(v_row.carrier, ''),
        'previous_product', NULLIF(v_row.previous_product, ''),
        'monthly_premium', _parse_import_number(v_row.monthly_premium),
        'start_date', _parse_import_date(v_row.start_date),
        'cancellation_date', _parse_import_datetime(v_row.cancellation_date),
        'iua_amount', NULLIF(v_row.iua_amount, ''),
        'add_on_product', NULLIF(v_row.add_on_product, ''),
        'vision', NULLIF(v_row.vision, ''),
        'dental', NULLIF(v_row.dental, ''),
        'commission_percentage', _parse_import_number(v_row.commission_percentage),
        'producer_commission', _parse_import_number(v_row.producer_commission),
        'amount_received', _parse_import_number(v_row.amount_received),
        'team_leader', NULLIF(v_row.team_leader, ''),
        'team_leader_monthly', _parse_import_number(v_row.team_leader_monthly),
        'team_leader_referral', _parse_import_number(v_row.team_leader_referral),
        'director', NULLIF(v_row.director, ''),
        'director_monthly', _parse_import_number(v_row.director_monthly),
        'director_referral', _parse_import_number(v_row.director_referral),
        'affiliate_referral', NULLIF(v_row.affiliate_referral, ''),
        'affiliate_rep_monthly', _parse_import_number(v_row.affiliate_rep_monthly),
        'referral_fee', _parse_import_number(v_row.referral_fee),
        'date_referral_paid', _parse_import_date(v_row.date_referral_paid),
        'referral_requirement_satisfied', NULLIF(v_row.referral_requirement_satisfied, ''),
        'declined', _parse_import_boolean(v_row.declined),
        'charge_waived', _parse_import_boolean(v_row.charge_waived),
        'household_annual_adj_gross', _parse_import_number(v_row.household_annual_adj_gross),
        'primary_ss_number', NULLIF(v_row.primary_ss_number, ''),
        'tax_id', NULLIF(v_row.tax_id, ''),
        'mpower_life_code', NULLIF(v_row.mpower_life_code, ''),
        'life_code_2nd', NULLIF(v_row.life_code_2nd, ''),
        'life_code_3rd', NULLIF(v_row.life_code_3rd, ''),
        'life_code_4th', NULLIF(v_row.life_code_4th, ''),
        'life_code_5th', NULLIF(v_row.life_code_5th, ''),
        'e123_member_id', NULLIF(v_row.e123_member_id, '')
      );

      v_data := v_data || jsonb_build_object(
        'portal_username', NULLIF(v_row.portal_username, ''),
        'portal_password', NULLIF(v_row.portal_password, ''),
        'cirrus_registration_date', _parse_import_date(v_row.cirrus_registration_date),
        'app_downloaded', _parse_import_boolean(v_row.app_downloaded),
        'select_conversion_completed', _parse_import_boolean(v_row.select_conversion_completed),
        'mec_submitted', _parse_import_boolean(v_row.mec_submitted),
        'mec_decision_confirmed', _parse_import_boolean(v_row.mec_decision_confirmed),
        'medical_release_form_on_file', _parse_import_boolean(v_row.medical_release_form_on_file),
        'permission_to_discuss_plan', _parse_import_boolean(v_row.permission_to_discuss_plan),
        'atap', NULLIF(v_row.atap, ''),
        'third_party_payor', NULLIF(v_row.third_party_payor, ''),
        'risk_assessment_paid', NULLIF(v_row.risk_assessment_paid, ''),
        'welcome_call_status', NULLIF(v_row.welcome_call_status, ''),
        'welcome_call_performed_by', NULLIF(v_row.welcome_call_performed_by, ''),
        'wc_outreach_date', _parse_import_date(v_row.wc_outreach_date),
        'fulfillment_letter_mailed', _parse_import_date(v_row.fulfillment_letter_mailed),
        'fulfillment_email_sent', _parse_import_date(v_row.fulfillment_email_sent),
        'complete_date', _parse_import_date(v_row.complete_date),
        'business_or_practice_name', NULLIF(v_row.business_or_practice_name, ''),
        'dpc_name', NULLIF(v_row.dpc_name, ''),
        'email_opt_out', _parse_import_boolean(v_row.email_opt_out),
        'preferred_method_of_communication', NULLIF(v_row.preferred_method_of_communication, ''),
        'unsubscribed_mode', NULLIF(v_row.unsubscribed_mode, ''),
        'unsubscribed_time', _parse_import_datetime(v_row.unsubscribed_time),
        'days_visited', _parse_import_number(v_row.days_visited),
        'average_time_spent_minutes', _parse_import_number(v_row.average_time_spent_minutes),
        'number_of_chats', _parse_import_number(v_row.number_of_chats),
        'most_recent_visit', _parse_import_datetime(v_row.most_recent_visit),
        'first_visit', _parse_import_datetime(v_row.first_visit),
        'first_page_visited', NULLIF(v_row.first_page_visited, ''),
        'referrer', NULLIF(v_row.referrer, ''),
        'visitor_score', _parse_import_number(v_row.visitor_score),
        'last_activity_time', _parse_import_datetime(v_row.last_activity_time),
        'notes_history', NULLIF(v_row.notes_history, ''),
        'created_by_name', NULLIF(v_row.created_by, ''),
        'modified_by_name', NULLIF(v_row.modified_by, ''),
        'zoho_created_time', _parse_import_datetime(v_row.created_time),
        'zoho_modified_time', _parse_import_datetime(v_row.modified_time),
        'locked', _parse_import_boolean(v_row.locked),
        'admin123', NULLIF(v_row.admin123, ''),
        'change_log_time', _parse_import_datetime(v_row.change_log_time),
        'data_processing_basis', NULLIF(v_row.data_processing_basis, ''),
        'connected_to_module', NULLIF(v_row.connected_to_module, ''),
        'connected_to_id', NULLIF(v_row.connected_to_id, '')
      );

      v_data := (
        SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
        FROM jsonb_each(v_data)
        WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb
      );

      v_market := classify_market_type(
        v_row.product, v_row.carrier, v_row.coverage_option, v_row.iua_amount
      );

      v_advisor_name := NULL;
      v_agent_name := NULL;

      IF v_market = 'healthshare' THEN
        v_advisor_name := COALESCE(NULLIF(TRIM(v_row.producer_name), ''), NULLIF(TRIM(v_row.contact_owner), ''));
      ELSIF v_market = 'traditional_insurance' THEN
        v_agent_name := COALESCE(NULLIF(TRIM(v_row.producer_name), ''), NULLIF(TRIM(v_row.contact_owner), ''));
      ELSE
        v_advisor_name := COALESCE(NULLIF(TRIM(v_row.producer_name), ''), NULLIF(TRIM(v_row.contact_owner), ''));
        v_agent_name := v_advisor_name;
      END IF;

      v_canonical_advisor_id := NULL;
      IF v_advisor_name IS NOT NULL THEN
        SELECT id INTO v_canonical_advisor_id FROM advisors
        WHERE organization_id = v_org_id
          AND LOWER(TRIM(first_name || ' ' || last_name)) = LOWER(TRIM(v_advisor_name))
        LIMIT 1;
        IF v_canonical_advisor_id IS NULL THEN
          SELECT id INTO v_canonical_advisor_id FROM advisors
          WHERE organization_id = v_org_id
            AND producer_code IS NOT NULL
            AND LOWER(TRIM(producer_code)) = LOWER(TRIM(v_advisor_name))
          LIMIT 1;
        END IF;
      END IF;

      v_norm_status := CASE
        WHEN v_market != 'unknown' AND (v_canonical_advisor_id IS NOT NULL OR v_agent_name IS NOT NULL)
          THEN 'normalized'
        WHEN v_market = 'unknown' THEN 'needs_review'
        WHEN v_advisor_name IS NOT NULL AND v_canonical_advisor_id IS NULL THEN 'needs_review'
        ELSE 'unresolved'
      END;

      IF v_existing_id IS NOT NULL THEN
        UPDATE crm_records SET
          title = COALESCE(NULLIF(v_row.contact_name, ''), NULLIF(TRIM(COALESCE(v_row.first_name, '') || ' ' || COALESCE(v_row.last_name, '')), ''), title),
          status = COALESCE(NULLIF(v_row.contact_status, ''), status),
          email = COALESCE(NULLIF(TRIM(v_row.email), ''), email),
          phone = COALESCE(NULLIF(v_row.phone, ''), phone),
          data = (SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb) FROM jsonb_each(data || v_data) WHERE value IS NOT NULL AND value != 'null'::jsonb AND value != '""'::jsonb),
          market_type = COALESCE(market_type, v_market),
          canonical_advisor_id = COALESCE(canonical_advisor_id, v_canonical_advisor_id),
          normalized_advisor_name = COALESCE(normalized_advisor_name, v_advisor_name),
          normalized_agent_name = COALESCE(normalized_agent_name, v_agent_name),
          normalization_status = COALESCE(normalization_status, v_norm_status),
          source_record_id = COALESCE(source_record_id, NULLIF(v_row.record_id, '')),
          import_source = COALESCE(import_source, 'zoho_csv'),
          updated_at = now()
        WHERE id = v_existing_id;
        v_updated := v_updated + 1;
      ELSE
        INSERT INTO crm_records (
          organization_id, module_id, title, status, email, phone, data,
          market_type, canonical_advisor_id,
          normalized_advisor_name, normalized_agent_name,
          normalization_status, normalization_notes,
          import_source, source_record_id,
          created_at, updated_at
        ) VALUES (
          v_org_id, v_module_id,
          COALESCE(NULLIF(v_row.contact_name, ''), TRIM(COALESCE(v_row.first_name, '') || ' ' || COALESCE(v_row.last_name, ''))),
          COALESCE(NULLIF(v_row.contact_status, ''), 'Active'),
          NULLIF(TRIM(v_row.email), ''), NULLIF(v_row.phone, ''),
          v_data, v_market, v_canonical_advisor_id,
          v_advisor_name, v_agent_name, v_norm_status,
          'Zoho CSV import (Phase 2 pipeline)', 'zoho_csv',
          NULLIF(v_row.record_id, ''),
          COALESCE(_parse_import_datetime(v_row.created_time), now()),
          COALESCE(_parse_import_datetime(v_row.modified_time), now())
        );
        v_inserted := v_inserted + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
    END;
  END LOOP;

  RETURN QUERY SELECT v_inserted, v_updated, v_skipped, v_errors;
END;
$function$;

-- public.upsert_contacts_from_staging()  [OBSOLETE_CANDIDATE, refs=6, risk=low]
CREATE OR REPLACE FUNCTION public.upsert_contacts_from_staging()
 RETURNS TABLE(inserted integer, updated integer, skipped integer, errors integer)
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_org_id uuid;
  v_module_id uuid;
  v_import_job_id uuid;
  v_inserted int := 0;
  v_updated int := 0;
  v_skipped int := 0;
  v_errors int := 0;
  v_row RECORD;
  v_existing_id uuid;
  v_data jsonb;
  v_new_record_id uuid;
BEGIN
  SELECT id INTO v_org_id FROM organizations LIMIT 1;
  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'No organization found. Create one first.';
  END IF;

  SELECT id INTO v_module_id FROM crm_modules
  WHERE organization_id = v_org_id AND key = 'contacts';
  IF v_module_id IS NULL THEN
    RAISE EXCEPTION 'Contacts module not found. Run seed first.';
  END IF;

  INSERT INTO crm_import_jobs (organization_id, module_id, source_type, file_name, status, started_at)
  VALUES (v_org_id, v_module_id, 'csv', 'Contacts_2026_02_10_upsert.csv', 'processing', now())
  RETURNING id INTO v_import_job_id;

  FOR v_row IN
    SELECT * FROM import_contacts_staging
    WHERE record_id IS NOT NULL
      AND record_id != 'Record Id'
      AND (first_name IS NOT NULL OR last_name IS NOT NULL)
    ORDER BY row_num
  LOOP
    BEGIN
      v_existing_id := NULL;

      -- MATCH PRIORITY 1: By email
      IF NULLIF(TRIM(v_row.email), '') IS NOT NULL THEN
        SELECT id INTO v_existing_id
        FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND LOWER(email) = LOWER(TRIM(v_row.email))
        ORDER BY updated_at DESC LIMIT 1;
      END IF;

      -- MATCH PRIORITY 2: By Zoho Record Id
      IF v_existing_id IS NULL AND NULLIF(v_row.record_id, '') IS NOT NULL THEN
        SELECT id INTO v_existing_id
        FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND data->>'zoho_record_id' = v_row.record_id
        LIMIT 1;
      END IF;

      -- MATCH PRIORITY 3: By first_name + last_name + phone
      IF v_existing_id IS NULL
         AND NULLIF(v_row.first_name, '') IS NOT NULL
         AND NULLIF(v_row.last_name, '') IS NOT NULL
         AND NULLIF(v_row.phone, '') IS NOT NULL
      THEN
        SELECT id INTO v_existing_id
        FROM crm_records
        WHERE organization_id = v_org_id AND module_id = v_module_id
          AND LOWER(data->>'first_name') = LOWER(v_row.first_name)
          AND LOWER(data->>'last_name') = LOWER(v_row.last_name)
          AND phone = v_row.phone
        ORDER BY updated_at DESC LIMIT 1;
      END IF;

      -- Build JSONB data in 4 chunks to stay under 100-arg limit
      -- Chunk 1: basic info + contact details (34 keys = 68 args)
      v_data := jsonb_build_object(
        'zoho_record_id', NULLIF(v_row.record_id, ''),
        'zoho_contact_owner_id', NULLIF(v_row.contact_owner_id, ''),
        'zoho_producer_id', NULLIF(v_row.producer_name_id, ''),
        'first_name', NULLIF(v_row.first_name, ''),
        'last_name', NULLIF(v_row.last_name, ''),
        'contact_name', NULLIF(v_row.contact_name, ''),
        'salutation', NULLIF(v_row.salutation, ''),
        'middle_initial', NULLIF(v_row.middle_initial, ''),
        'title', NULLIF(v_row.title, ''),
        'date_of_birth', _parse_import_date(v_row.date_of_birth),
        'birth_month', NULLIF(v_row.birth_month, ''),
        'primary_member_gender', NULLIF(v_row.primary_member_gender, ''),
        'marital_status', NULLIF(v_row.marital_status, ''),
        'secondary_email', NULLIF(v_row.secondary_email, ''),
        'mobile', NULLIF(v_row.mobile, ''),
        'work_phone', NULLIF(v_row.work_phone, ''),
        'fax', NULLIF(v_row.fax, ''),
        'mailing_street', NULLIF(v_row.mailing_street, ''),
        'mailing_city', NULLIF(v_row.mailing_city, ''),
        'mailing_state', NULLIF(v_row.mailing_state, ''),
        'mailing_zip', NULLIF(v_row.mailing_zip, ''),
        'contact_status', NULLIF(v_row.contact_status, ''),
        'contact_owner', NULLIF(v_row.contact_owner, ''),
        'lead_source', NULLIF(v_row.lead_source, ''),
        'affiliate', NULLIF(v_row.affiliate, ''),
        'producer_name', NULLIF(v_row.producer_name, ''),
        'referral_source', NULLIF(v_row.referral_source, ''),
        'referring_member', NULLIF(v_row.referring_member, ''),
        'tag', NULLIF(v_row.tag, ''),
        'territories', NULLIF(v_row.territories, ''),
        'company_association', NULLIF(v_row.company_association, ''),
        'data_source', NULLIF(v_row.data_source, ''),
        'spouse', NULLIF(v_row.spouse, ''),
        'spouse_dob', _parse_import_date(v_row.spouse_dob)
      );

      -- Chunk 2: spouse + children (36 keys = 72 args)
      v_data := v_data || jsonb_build_object(
        'spouse_ss_number', NULLIF(v_row.spouse_ss_number, ''),
        'spouse_address', NULLIF(v_row.spouse_address, ''),
        'spouse_phone_number', NULLIF(v_row.spouse_phone_number, ''),
        'spouse_email', NULLIF(v_row.spouse_email, ''),
        'child_1', NULLIF(v_row.child_1, ''),
        'child_1_dob', _parse_import_date(v_row.child_1_dob),
        'child_1_ss_number', NULLIF(v_row.child_1_ss_number, ''),
        'child_1_address', NULLIF(v_row.child_1_address, ''),
        'child_1_phone_number', NULLIF(v_row.child_1_phone_number, ''),
        'child_1_email', NULLIF(v_row.child_1_email, ''),
        'child_2', NULLIF(v_row.child_2, ''),
        'child_2_dob', _parse_import_date(v_row.child_2_dob),
        'child_2_ss_number', NULLIF(v_row.child_2_ss_number, ''),
        'child_2_address', NULLIF(v_row.child_2_address, ''),
        'child_2_phone_number', NULLIF(v_row.child_2_phone_number, ''),
        'child_2_email', NULLIF(v_row.child_2_email, ''),
        'child_3', NULLIF(v_row.child_3, ''),
        'child_3_dob', _parse_import_date(v_row.child_3_dob),
        'child_3_ss_number', NULLIF(v_row.child_3_ss_number, ''),
        'child_3_address', NULLIF(v_row.child_3_address, ''),
        'child_3_phone_number', NULLIF(v_row.child_3_phone_number, ''),
        'child_3_email', NULLIF(v_row.child_3_email, ''),
        'child_4', NULLIF(v_row.child_4, ''),
        'child_4_dob', _parse_import_date(v_row.child_4_dob),
        'child_4_ss_number', NULLIF(v_row.child_4_ss_number, ''),
        'child_4_address', NULLIF(v_row.child_4_address, ''),
        'child_4_phone_number', NULLIF(v_row.child_4_phone_number, ''),
        'child_4_email', NULLIF(v_row.child_4_email, ''),
        'child_5', NULLIF(v_row.child_5, ''),
        'child_5_dob', _parse_import_date(v_row.child_5_dob),
        'child_5_ss_number', NULLIF(v_row.child_5_ss_number, ''),
        'child_5_address', NULLIF(v_row.child_5_address, ''),
        'child_5_phone_number', NULLIF(v_row.child_5_phone_number, ''),
        'child_5_email', NULLIF(v_row.child_5_email, ''),
        'product', NULLIF(v_row.product, ''),
        'coverage_option', NULLIF(v_row.coverage_option, '')
      );

      -- Chunk 3: insurance + financial (36 keys = 72 args)
      v_data := v_data || jsonb_build_object(
        'carrier', NULLIF(v_row.carrier, ''),
        'previous_product', NULLIF(v_row.previous_product, ''),
        'monthly_premium', _parse_import_number(v_row.monthly_premium),
        'start_date', _parse_import_date(v_row.start_date),
        'cancellation_date', _parse_import_datetime(v_row.cancellation_date),
        'iua_amount', NULLIF(v_row.iua_amount, ''),
        'add_on_product', NULLIF(v_row.add_on_product, ''),
        'vision', NULLIF(v_row.vision, ''),
        'dental', NULLIF(v_row.dental, ''),
        'commission_percentage', _parse_import_number(v_row.commission_percentage),
        'producer_commission', _parse_import_number(v_row.producer_commission),
        'amount_received', _parse_import_number(v_row.amount_received),
        'team_leader', NULLIF(v_row.team_leader, ''),
        'team_leader_monthly', _parse_import_number(v_row.team_leader_monthly),
        'team_leader_referral', _parse_import_number(v_row.team_leader_referral),
        'director', NULLIF(v_row.director, ''),
        'director_monthly', _parse_import_number(v_row.director_monthly),
        'director_referral', _parse_import_number(v_row.director_referral),
        'affiliate_referral', NULLIF(v_row.affiliate_referral, ''),
        'affiliate_rep_monthly', _parse_import_number(v_row.affiliate_rep_monthly),
        'referral_fee', _parse_import_number(v_row.referral_fee),
        'date_referral_paid', _parse_import_date(v_row.date_referral_paid),
        'referral_requirement_satisfied', NULLIF(v_row.referral_requirement_satisfied, ''),
        'declined', _parse_import_boolean(v_row.declined),
        'charge_waived', _parse_import_boolean(v_row.charge_waived),
        'household_annual_adj_gross', _parse_import_number(v_row.household_annual_adj_gross),
        'primary_ss_number', NULLIF(v_row.primary_ss_number, ''),
        'tax_id', NULLIF(v_row.tax_id, ''),
        'mpower_life_code', NULLIF(v_row.mpower_life_code, ''),
        'life_code_2nd', NULLIF(v_row.life_code_2nd, ''),
        'life_code_3rd', NULLIF(v_row.life_code_3rd, ''),
        'life_code_4th', NULLIF(v_row.life_code_4th, ''),
        'life_code_5th', NULLIF(v_row.life_code_5th, ''),
        'e123_member_id', NULLIF(v_row.e123_member_id, ''),
        'portal_username', NULLIF(v_row.portal_username, ''),
        'portal_password', NULLIF(v_row.portal_password, '')
      );

      -- Chunk 4: portal + analytics + metadata (30 keys = 60 args)
      v_data := v_data || jsonb_build_object(
        'cirrus_registration_date', _parse_import_date(v_row.cirrus_registration_date),
        'app_downloaded', _parse_import_boolean(v_row.app_downloaded),
        'select_conversion_completed', _parse_import_boolean(v_row.select_conversion_completed),
        'mec_submitted', _parse_import_boolean(v_row.mec_submitted),
        'mec_decision_confirmed', _parse_import_boolean(v_row.mec_decision_confirmed),
        'medical_release_form_on_file', _parse_import_boolean(v_row.medical_release_form_on_file),
        'permission_to_discuss_plan', _parse_import_boolean(v_row.permission_to_discuss_plan),
        'atap', NULLIF(v_row.atap, ''),
        'third_party_payor', NULLIF(v_row.third_party_payor, ''),
        'risk_assessment_paid', NULLIF(v_row.risk_assessment_paid, ''),
        'welcome_call_status', NULLIF(v_row.welcome_call_status, ''),
        'welcome_call_performed_by', NULLIF(v_row.welcome_call_performed_by, ''),
        'wc_outreach_date', _parse_import_date(v_row.wc_outreach_date),
        'fulfillment_letter_mailed', _parse_import_date(v_row.fulfillment_letter_mailed),
        'fulfillment_email_sent', _parse_import_date(v_row.fulfillment_email_sent),
        'complete_date', _parse_import_date(v_row.complete_date),
        'business_or_practice_name', NULLIF(v_row.business_or_practice_name, ''),
        'dpc_name', NULLIF(v_row.dpc_name, ''),
        'email_opt_out', _parse_import_boolean(v_row.email_opt_out),
        'preferred_method_of_communication', NULLIF(v_row.preferred_method_of_communication, ''),
        'unsubscribed_mode', NULLIF(v_row.unsubscribed_mode, ''),
        'unsubscribed_time', _parse_import_datetime(v_row.unsubscribed_time),
        'days_visited', _parse_import_number(v_row.days_visited),
        'average_time_spent_minutes', _parse_import_number(v_row.average_time_spent_minutes),
        'number_of_chats', _parse_import_number(v_row.number_of_chats),
        'most_recent_visit', _parse_import_datetime(v_row.most_recent_visit),
        'first_visit', _parse_import_datetime(v_row.first_visit),
        'first_page_visited', NULLIF(v_row.first_page_visited, ''),
        'referrer', NULLIF(v_row.referrer, ''),
        'visitor_score', _parse_import_number(v_row.visitor_score)
      );

      -- Chunk 5: remaining metadata (6 keys = 12 args)
      v_data := v_data || jsonb_build_object(
        'last_activity_time', _parse_import_datetime(v_row.last_activity_time),
        'notes_history', NULLIF(v_row.notes_history, ''),
        'created_by_name', NULLIF(v_row.created_by, ''),
        'modified_by_name', NULLIF(v_row.modified_by, ''),
        'zoho_created_time', _parse_import_datetime(v_row.created_time),
        'zoho_modified_time', _parse_import_datetime(v_row.modified_time),
        'locked', _parse_import_boolean(v_row.locked),
        'admin123', NULLIF(v_row.admin123, ''),
        'change_log_time', _parse_import_datetime(v_row.change_log_time),
        'data_processing_basis', NULLIF(v_row.data_processing_basis, ''),
        'connected_to_module', NULLIF(v_row.connected_to_module, ''),
        'connected_to_id', NULLIF(v_row.connected_to_id, '')
      );

      -- Strip null values
      v_data := (
        SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
        FROM jsonb_each(v_data)
        WHERE value IS NOT NULL
          AND value != 'null'::jsonb
          AND value != '""'::jsonb
      );

      -- UPSERT
      IF v_existing_id IS NOT NULL THEN
        UPDATE crm_records SET
          title = COALESCE(
            NULLIF(v_row.contact_name, ''),
            NULLIF(TRIM(COALESCE(v_row.first_name, '') || ' ' || COALESCE(v_row.last_name, '')), ''),
            title
          ),
          status = COALESCE(NULLIF(v_row.contact_status, ''), status),
          email = COALESCE(NULLIF(TRIM(v_row.email), ''), email),
          phone = COALESCE(NULLIF(v_row.phone, ''), phone),
          data = (
            SELECT COALESCE(jsonb_object_agg(key, value), '{}'::jsonb)
            FROM jsonb_each(data || v_data)
            WHERE value IS NOT NULL
              AND value != 'null'::jsonb
              AND value != '""'::jsonb
          ),
          updated_at = now()
        WHERE id = v_existing_id;

        INSERT INTO crm_import_rows (job_id, row_index, record_id, status, match_type)
        VALUES (v_import_job_id, v_row.row_num, v_existing_id, 'updated', 'email');
        v_updated := v_updated + 1;
      ELSE
        INSERT INTO crm_records (
          organization_id, module_id, title, status, email, phone, data, created_at, updated_at
        ) VALUES (
          v_org_id, v_module_id,
          COALESCE(
            NULLIF(v_row.contact_name, ''),
            TRIM(COALESCE(v_row.first_name, '') || ' ' || COALESCE(v_row.last_name, ''))
          ),
          COALESCE(NULLIF(v_row.contact_status, ''), 'Active'),
          NULLIF(TRIM(v_row.email), ''),
          NULLIF(v_row.phone, ''),
          v_data,
          COALESCE(_parse_import_datetime(v_row.created_time), now()),
          COALESCE(_parse_import_datetime(v_row.modified_time), now())
        )
        RETURNING id INTO v_new_record_id;

        INSERT INTO crm_import_rows (job_id, row_index, record_id, status, match_type)
        VALUES (v_import_job_id, v_row.row_num, v_new_record_id, 'inserted', 'new');
        v_inserted := v_inserted + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      INSERT INTO crm_import_rows (job_id, row_index, status, error)
      VALUES (v_import_job_id, v_row.row_num, 'error', SQLERRM);
      v_errors := v_errors + 1;
    END;
  END LOOP;

  UPDATE crm_import_jobs SET
    status = 'completed',
    completed_at = now(),
    total_rows = v_inserted + v_updated + v_skipped + v_errors,
    processed_rows = v_inserted + v_updated + v_skipped + v_errors,
    inserted_count = v_inserted,
    updated_count = v_updated,
    skipped_count = v_skipped,
    error_count = v_errors
  WHERE id = v_import_job_id;

  RAISE NOTICE 'Contacts upsert complete: % inserted, % updated, % skipped, % errors',
    v_inserted, v_updated, v_skipped, v_errors;
  RETURN QUERY SELECT v_inserted, v_updated, v_skipped, v_errors;
END;
$function$;

-- public.upsert_leads_batch(p_offset integer, p_limit integer, p_org_id uuid)  [MECHANICAL, refs=5, risk=low]
CREATE OR REPLACE FUNCTION public.upsert_leads_batch(p_offset integer DEFAULT 0, p_limit integer DEFAULT 500, p_org_id uuid DEFAULT NULL::uuid)
 RETURNS TABLE(inserted integer, updated integer, skipped integer, errors integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
 SET statement_timeout TO '120s'
AS $function$
DECLARE
  v_org_id      uuid;
  v_module_id   uuid;
  v_inserted    int := 0;
  v_updated     int := 0;
  v_skipped     int := 0;
  v_errors      int := 0;
  v_row         import_leads_staging%ROWTYPE;
  v_existing_id uuid;
  v_match_type  text;
  v_data        jsonb;
  v_title       text;
BEGIN
  -- Resolve target organization
  IF p_org_id IS NOT NULL THEN
    v_org_id := p_org_id;
  ELSE
    -- Legacy fallback to match existing contacts pipeline behavior
    SELECT id INTO v_org_id FROM organizations ORDER BY created_at LIMIT 1;
  END IF;

  IF v_org_id IS NULL THEN
    RAISE EXCEPTION 'upsert_leads_batch: no organization resolved';
  END IF;

  -- Resolve leads module for this org
  SELECT id INTO v_module_id
    FROM crm_modules
   WHERE organization_id = v_org_id
     AND key = 'leads'
   LIMIT 1;

  IF v_module_id IS NULL THEN
    RAISE EXCEPTION 'upsert_leads_batch: leads module not found for org %', v_org_id;
  END IF;

  FOR v_row IN
    SELECT *
      FROM import_leads_staging
     ORDER BY row_num
     LIMIT p_limit OFFSET p_offset
  LOOP
    BEGIN
      v_existing_id := NULL;
      v_match_type  := NULL;

      -- Build data payload from all staging columns. Empty strings -> NULL.
      v_data := jsonb_strip_nulls(
        to_jsonb(v_row) - 'row_num'
      );
      -- Add canonical aliases used by the existing pipeline
      v_data := v_data || jsonb_build_object(
        'zoho_record_id', NULLIF(v_row.record_id, ''),
        'zoho_module',    'Leads'
      );

      -- Compute title (used by indexed search). generate_record_title() handles fallback.
      v_title := NULLIF(
        TRIM(COALESCE(v_row.first_name, '') || ' ' || COALESCE(v_row.last_name, '')),
        ''
      );
      v_title := COALESCE(v_title, NULLIF(v_row.lead_name, ''), NULLIF(v_row.company, ''), NULLIF(v_row.email, ''), 'Untitled');

      -- ----------------------------------------------------------------------
      -- 4-tier dedup (mirrors upsert_contacts_batch precedence)
      -- ----------------------------------------------------------------------
      -- Tier 1: email
      IF v_row.email IS NOT NULL AND TRIM(v_row.email) <> '' THEN
        SELECT id INTO v_existing_id
          FROM crm_records
         WHERE organization_id    = v_org_id
           AND module_id = v_module_id
           AND LOWER(email) = LOWER(TRIM(v_row.email))
         LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_type := 'email'; END IF;
      END IF;

      -- Tier 2: zoho_record_id
      IF v_existing_id IS NULL AND v_row.record_id IS NOT NULL AND v_row.record_id <> '' THEN
        SELECT id INTO v_existing_id
          FROM crm_records
         WHERE organization_id    = v_org_id
           AND module_id = v_module_id
           AND data->>'zoho_record_id' = v_row.record_id
         LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_type := 'zoho_record_id'; END IF;
      END IF;

      -- Tier 3: name + phone
      IF v_existing_id IS NULL
         AND v_row.first_name IS NOT NULL AND TRIM(v_row.first_name) <> ''
         AND v_row.last_name  IS NOT NULL AND TRIM(v_row.last_name)  <> ''
         AND v_row.phone      IS NOT NULL AND TRIM(v_row.phone)      <> '' THEN
        SELECT id INTO v_existing_id
          FROM crm_records
         WHERE organization_id    = v_org_id
           AND module_id = v_module_id
           AND LOWER(data->>'first_name') = LOWER(TRIM(v_row.first_name))
           AND LOWER(data->>'last_name')  = LOWER(TRIM(v_row.last_name))
           AND phone = v_row.phone
         LIMIT 1;
        IF v_existing_id IS NOT NULL THEN v_match_type := 'name_phone'; END IF;
      END IF;

      -- ----------------------------------------------------------------------
      -- UPSERT
      -- ----------------------------------------------------------------------
      IF v_existing_id IS NOT NULL THEN
        -- SAFE MERGE: existing-wins semantics. Right side of `||` wins for
        -- shared keys, so v_data only contributes brand-new keys; any field
        -- already present in `data` (including staff-edited values) is
        -- preserved. New JSONB keys from the latest Zoho export still land,
        -- but existing values are never overwritten. Top-level columns
        -- already use COALESCE(existing, incoming) for the same reason.
        UPDATE crm_records SET
          data       = COALESCE(v_data, '{}'::jsonb) || COALESCE(data, '{}'::jsonb),
          email      = COALESCE(NULLIF(email, ''), NULLIF(v_row.email, '')),
          phone      = COALESCE(NULLIF(phone, ''), NULLIF(v_row.phone, ''), NULLIF(v_row.mobile, '')),
          status     = COALESCE(NULLIF(status, ''), NULLIF(v_row.lead_status, '')),
          title      = COALESCE(NULLIF(title, ''), v_title),
          updated_at = now()
        WHERE id = v_existing_id;
        v_updated := v_updated + 1;
      ELSE
        INSERT INTO crm_records (
          organization_id, module_id, title, status, email, phone, data
        ) VALUES (
          v_org_id,
          v_module_id,
          v_title,
          NULLIF(v_row.lead_status, ''),
          NULLIF(v_row.email, ''),
          COALESCE(NULLIF(v_row.phone, ''), NULLIF(v_row.mobile, '')),
          v_data
        );
        v_inserted := v_inserted + 1;
      END IF;

    EXCEPTION WHEN OTHERS THEN
      v_errors := v_errors + 1;
      RAISE WARNING 'upsert_leads_batch row_num=% sqlerrm=%', v_row.row_num, SQLERRM;
    END;
  END LOOP;

  RETURN QUERY SELECT v_inserted, v_updated, v_skipped, v_errors;
END
$function$;

-- public.upsert_recent_view(p_org_id uuid, p_user_id uuid, p_record_id uuid, p_module_id uuid)  [WRITES_ORG_ID, refs=1, risk=low]
CREATE OR REPLACE FUNCTION public.upsert_recent_view(p_org_id uuid, p_user_id uuid, p_record_id uuid, p_module_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  INSERT INTO crm_recent_views (organization_id, user_id, record_id, module_id, viewed_at, view_count)
  VALUES (p_org_id, p_user_id, p_record_id, p_module_id, now(), 1)
  ON CONFLICT (user_id, record_id)
  DO UPDATE SET
    viewed_at = now(),
    view_count = crm_recent_views.view_count + 1;

  -- Keep only last 100 records per user
  DELETE FROM crm_recent_views
  WHERE user_id = p_user_id
  AND id NOT IN (
    SELECT id FROM crm_recent_views
    WHERE user_id = p_user_id
    ORDER BY viewed_at DESC
    LIMIT 100
  );
END;
$function$;
